class SectionErrorBoundary extends Component {
 constructor(props) {
 super(props)
 this.state = { hasError:false, error:null }
 }
 static getDerivedStateFromError(error) {
 return { hasError:true, error }
 }
 componentDidUpdate(prevProps) {
 if (prevProps.resetKey!== this.props.resetKey && this.state.hasError) {
 this.setState({ hasError:false, error:null })
 }
 }
 componentDidCatch(error, info) {
 console.error('Admin section crashed:', error, info)
 }
 render() {
 if (this.state.hasError) {
 return (
 <div style={{ background:'white', border:'2px solid #ca1b1b', borderRadius:'14px', padding:'20px', maxWidth:'760px' }}>
 <h2 style={{ color:'#ca1b1b', margin:'0 0 10px' }}> This section failed to load</h2>
 <p style={{ color:'#555', fontSize:'13px', lineHeight:1.6, margin:'0 0 10px' }}>The app caught the error so the screen will not go blank. Please copy the message below if you need help checking the exact database/table issue.</p>
 <pre style={{ background:'#fff5f5', border:'1px solid #ffd0d0', borderRadius:'10px', padding:'12px', overflowX:'auto', color:'#8b0000', fontSize:'12px' }}>{String(this.state.error?.message || this.state.error || 'Unknown error')}</pre>
 <button style={{ background:'#ca1b1b', color:'white', border:'none', borderRadius:'10px', padding:'10px 18px', fontWeight:'bold', cursor:'pointer' }} onClick={()=>this.setState({ hasError:false, error:null })}>Try Again</button>
 </div>
 )
 }
 return this.props.children
 }
}

// Helpers 
function getTodayDate() {
 const d = new Date()
 d.setMinutes(d.getMinutes() - d.getTimezoneOffset())
 return d.toISOString().slice(0, 10)
}
function nowTime() { return new Date().toLocaleTimeString('en-GB', { hour12: false }) }
function minutesFromTime(t) { const [h, m] = String(t||'00:00').split(':').map(Number); return (Number(h)||0) * 60 + (Number(m)||0) }

function getPHDateTimeParts(asOf = new Date()) {
 const parts = new Intl.DateTimeFormat('en-GB', {
 timeZone: PH_TIME_ZONE,
 year:'numeric', month:'2-digit', day:'2-digit',
 hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false
 }).formatToParts(asOf).reduce((acc, part) => {
 if (part.type!== 'literal') acc[part.type] = part.value
 return acc
 }, {})

 const hour = Number(parts.hour) === 24? 0: Number(parts.hour || 0)
 const minute = Number(parts.minute || 0)
 const second = Number(parts.second || 0)

 return {
 date: `${parts.year}-${parts.month}-${parts.day}`,
 time: `${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}:${String(second).padStart(2,'0')}`,
 hour,
 minute,
 second,
 totalMinutes: hour * 60 + minute
 }
}

function getPHDateOffsetString(days = 0, asOf = new Date()) {
 const ph = getPHDateTimeParts(asOf)
 const [y, m, d] = String(ph.date || '').split('-').map(Number)
 const date = new Date(y || new Date().getFullYear(), (m || 1) - 1, d || 1)
 date.setDate(date.getDate() + safeNum(days, 0))
 date.setHours(0, 0, 0, 0)
 return formatDateLocal(date)
}

function getOrderCutoffStatus(targetDeliveryDate = null, asOf = new Date()) {
 // Order cut-off has been completely removed.
 // Resellers and admins can create, edit, and approve orders/invoices anytime.
 const ph = getPHDateTimeParts(asOf)
 const tomorrowDate = getPHDateOffsetString(1, asOf)
 const targetDate = targetDeliveryDate? String(targetDeliveryDate).slice(0, 10): tomorrowDate
 return {
 locked:false,
 timeLocked:false,
 appliesToTomorrow:false,
 targetDate,
 tomorrowDate,
 date: ph.date,
 time: ph.time,
 cutoffTime:null,
 cutoffLabel:'No cut-off',
 message:'Order cut-off removed. Orders, invoices, quantity edits, and order approvals are allowed anytime.'
 }
}


function getDefaultResellerOrderDeliveryDate(asOf = new Date()) {
 // No cut-off: tomorrow remains the default delivery date at any time of day.
 return getPHDateOffsetString(1, asOf)
}

function diffMinutesAcrossMidnight(startTime, endTime) {
 const start = minutesFromTime(startTime)
 let end = minutesFromTime(endTime)
 if (end < start) end += 24 * 60
 return Math.max(0, end - start)
}
function diffFromShiftEndMinutes(shiftStart, shiftEnd, clockOutTime, actualTimeIn) {
 if (!shiftEnd) return 0
 let end = minutesFromTime(shiftEnd)
 let out = minutesFromTime(clockOutTime)
 const start = shiftStart? minutesFromTime(shiftStart): (actualTimeIn? minutesFromTime(actualTimeIn): null)
 const actualCrossedMidnight = actualTimeIn && minutesFromTime(clockOutTime) < minutesFromTime(actualTimeIn)
 const scheduledOvernight = start!== null && end <= start
 if (scheduledOvernight) end += 24 * 60
 if ((start!== null && out < start) || actualCrossedMidnight) out += 24 * 60
 return out - end
}

function getShiftRelativeMinute(timeValue, shiftStartMinute, shiftEndMinute) {
 let minute = minutesFromTime(timeValue)
 if (shiftEndMinute > 24 * 60 && minute < shiftStartMinute) minute += 24 * 60
 return minute
}

function getMinuteOverlap(startA, endA, startB, endB) {
 const start = Math.max(startA, startB)
 const end = Math.min(endA, endB)
 return end > start ? end - start : 0
}

function calculateNightDifferentialMinutes(timeIn, timeOut, breakRows = []) {
 if (!timeIn || !timeOut) return 0
 const shiftStart = minutesFromTime(timeIn)
 let shiftEnd = minutesFromTime(timeOut)
 if (shiftEnd < shiftStart) shiftEnd += 24 * 60
 if (shiftEnd <= shiftStart) return 0

 // Night differential window is 10:00 PM to 6:00 AM.
 // Break minutes inside this window are excluded from night differential pay.
 const nightWindows = [
  [0, 6 * 60],
  [22 * 60, 30 * 60],
  [46 * 60, 54 * 60]
 ]

 let paidNightMinutes = 0
 nightWindows.forEach(([start, end]) => {
  paidNightMinutes += getMinuteOverlap(shiftStart, shiftEnd, start, end)
 })

 let breakNightMinutes = 0
 ;(breakRows || []).forEach(breakRow => {
  if (!breakRow?.break_out || !breakRow?.break_in) return
  const breakStartRaw = minutesFromTime(breakRow.break_out)
  let breakStart = getShiftRelativeMinute(breakRow.break_out, shiftStart, shiftEnd)
  let breakEnd = minutesFromTime(breakRow.break_in)
  if (shiftEnd > 24 * 60 && breakEnd < shiftStart) breakEnd += 24 * 60
  if (breakEnd <= breakStart || breakEnd < breakStartRaw) breakEnd += 24 * 60
  if (breakEnd <= breakStart) return
  const cappedBreakStart = Math.max(breakStart, shiftStart)
  const cappedBreakEnd = Math.min(breakEnd, shiftEnd)
  if (cappedBreakEnd <= cappedBreakStart) return
  nightWindows.forEach(([start, end]) => {
   breakNightMinutes += getMinuteOverlap(cappedBreakStart, cappedBreakEnd, start, end)
  })
 })

 return Math.max(0, Math.round(paidNightMinutes - breakNightMinutes))
}



function getDTRDutyMinutes(log = {}) {
 if (!log || !log.time_in || !log.time_out || log.status === 'Absent') return 0
 if (Array.isArray(log._logs) && log._logs.length > 1) {
  return log._logs.reduce((sum, row) => sum + getDTRDutyMinutes(row), 0)
 }
 const rawMinutes = diffMinutesAcrossMidnight(log.time_in, log.time_out)
 const breakMinutes = safeNum(log.total_break_minutes, 0)
 return Math.max(0, Math.round(rawMinutes - breakMinutes))
}

function formatDutyHours(minutes = 0) {
 const total = Math.max(0, Math.round(safeNum(minutes, 0)))
 const hours = Math.floor(total / 60)
 const mins = total % 60
 return `${hours}h ${mins}m`
}

function isHolidayPayEligible(emp = {}, holidayType = '') {
 const type = String(holidayType || '').trim().toLowerCase()
 if (type === 'regular') return emp?.regular_holiday_pay_eligible !== false
 if (type === 'special') return emp?.special_holiday_pay_eligible !== false
 return true
}

function isMissingEmployeeHolidayEligibilityColumnError(error) {
 const msg = String(error?.message || error || '').toLowerCase()
 return msg.includes('regular_holiday_pay_eligible') || msg.includes('special_holiday_pay_eligible') || ((msg.includes('schema cache') || msg.includes('could not find') || msg.includes('column')) && msg.includes('holiday'))
}

function stripUnsupportedEmployeeOptionalColumns(payload = {}, error = null) {
 const clean = { ...payload }
 if (!error || isMissingPayrollCostColumnError(error)) delete clean.payroll_cost_type
 if (!error || isMissingEmployeeHolidayEligibilityColumnError(error)) {
  delete clean.regular_holiday_pay_eligible
  delete clean.special_holiday_pay_eligible
 }
 return clean
}

