function getDateOffsetString(days) {
 const d = new Date()
 d.setDate(d.getDate() + days)
 d.setMinutes(d.getMinutes() - d.getTimezoneOffset())
 return d.toISOString().slice(0, 10)
}
function roundPenaltyMinutes(min) { if (!min || min <= 10) return 0; return Math.ceil(min / 30) * 30 }
function safeNum(value, fallback = 0) {
 const n = Number(value)
 return Number.isFinite(n)? n: fallback
}
function positiveNum(value, fallback = 1) {
 const n = safeNum(value, fallback)
 return n > 0? n: fallback
}
function php(a) { return `\u20B1${safeNum(a).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }
function moneyRound(value) { return Math.round((safeNum(value, 0) + Number.EPSILON) * 100) / 100 }
function isMoneySettled(balance) { return moneyRound(balance) <= 0.01 }
function genSerial(start, idx) { return `PS-${start.slice(0,7).replace('-','')}-${String(idx+1).padStart(3,'0')}` }
function getDistanceMeters(la1,lo1,la2,lo2) {
 const R=6371000,dL=(la2-la1)*Math.PI/180,dO=(lo2-lo1)*Math.PI/180
 const a=Math.sin(dL/2)**2+Math.cos(la1*Math.PI/180)*Math.cos(la2*Math.PI/180)*Math.sin(dO/2)**2
 return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))
}

function parseLocalDate(value) {
 if (!value) return null
 const clean = String(value).slice(0, 10)
 const [y, m, d] = clean.split('-').map(Number)
 if (!y ||!m ||!d) return null
 const date = new Date(y, m - 1, d)
 date.setHours(0, 0, 0, 0)
 return Number.isNaN(date.getTime())? null: date
}

function formatDateLocal(date) {
 const d = new Date(date)
 d.setHours(0, 0, 0, 0)
 d.setMinutes(d.getMinutes() - d.getTimezoneOffset())
 return d.toISOString().slice(0, 10)
}

function addMonthsClampedDateString(dateStr, monthOffset = 0) {
 const start = parseLocalDate(dateStr)
 if (!start) return ''
 const targetYear = start.getFullYear()
 const targetMonth = start.getMonth() + Number(monthOffset || 0)
 const dueDay = start.getDate()
 const lastDayOfTargetMonth = new Date(targetYear, targetMonth + 1, 0).getDate()
 const out = new Date(targetYear, targetMonth, Math.min(dueDay, lastDayOfTargetMonth))
 out.setHours(0, 0, 0, 0)
 return formatDateLocal(out)
}

function getMonthlyPayableDueDates(startDueDate, repeatUntilDate, maxMonths = 60) {
 const start = parseLocalDate(startDueDate)
 const end = parseLocalDate(repeatUntilDate)
 if (!start ||!end || end < start) return []

 const dates = []
 for (let i = 0; i < maxMonths; i++) {
 const dueDate = addMonthsClampedDateString(startDueDate, i)
 const due = parseLocalDate(dueDate)
 if (!due || due > end) break
 dates.push(dueDate)
 }
 return dates
}

function addYearsLocal(date, years) {
 const d = new Date(date)
 const originalMonth = d.getMonth()
 d.setFullYear(d.getFullYear() + years)
 // Keep leap-day hires stable by moving overflowed dates to the last day of the target month.
 if (d.getMonth()!== originalMonth) d.setDate(0)
 d.setHours(0, 0, 0, 0)
 return d
}

function addMonthsLocal(date, months) {
 const d = new Date(date)
 const originalDate = d.getDate()
 d.setDate(1)
 d.setMonth(d.getMonth() + safeNum(months, 0))
 const lastDay = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()
 d.setDate(Math.min(originalDate, lastDay))
 d.setHours(0, 0, 0, 0)
 return d
}

function daysInclusive(startDate, endDate) {
 const start = parseLocalDate(startDate)
 const end = parseLocalDate(endDate)
 if (!start ||!end || end < start) return 0
 return Math.floor((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1
}


function addDaysToDateString(dateStr, days = 0) {
 const date = parseLocalDate(dateStr)
 if (!date) return ''
 date.setDate(date.getDate() + safeNum(days, 0))
 return formatDateLocal(date)
}

function buildDateRangeRows(startDate, endDate, mapper = null) {
 const totalDays = daysInclusive(startDate, endDate)
 return Array.from({ length: totalDays }, (_, i) => {
  const dateStr = addDaysToDateString(startDate, i)
  const date = parseLocalDate(dateStr)
  const row = {
   dateStr,
   day: date? date.getDate(): i + 1,
   dayName: date? date.toLocaleDateString('en-US', { weekday:'short' }): '',
   index:i
  }
  return typeof mapper === 'function'? mapper(row, i): row
 })
}

function pad2(value) {
 return String(value).padStart(2, '0')
}

function yearMonthFromParts(year, month) {
 return `${year}-${pad2(month)}`
}

function shiftYearMonth(yearMonth, monthOffset = 0) {
 const [y, m] = String(yearMonth || '').split('-').map(Number)
 if (!y || !m) return ''
 const date = new Date(y, m - 1 + safeNum(monthOffset, 0), 1)
 return yearMonthFromParts(date.getFullYear(), date.getMonth() + 1)
}

function getPayrollCutoffPeriodFromParts(yearMonth, cutoffType = '11-25') {
 const [y, m] = String(yearMonth || '').split('-').map(Number)
 if (!y || !m) return null
 const ymDate = (year, month, day) => `${year}-${pad2(month)}-${pad2(day)}`
 if (cutoffType === '26-10') {
  const nextYear = m === 12? y + 1: y
  const nextMonth = m === 12? 1: m + 1
  return {
   key:`${yearMonth}|26-10`,
   type:'26-10',
   start:ymDate(y, m, 26),
   end:ymDate(nextYear, nextMonth, 10),
   label:`${formatDateForDisplay(ymDate(y, m, 26))} – ${formatDateForDisplay(ymDate(nextYear, nextMonth, 10))} (26th–10th)`
  }
 }
 return {
  key:`${yearMonth}|11-25`,
  type:'11-25',
  start:ymDate(y, m, 11),
  end:ymDate(y, m, 25),
  label:`${formatDateForDisplay(ymDate(y, m, 11))} – ${formatDateForDisplay(ymDate(y, m, 25))} (11th–25th)`
 }
}

function getDTRCutoffPeriodFromKey(key) {
 const [yearMonth, type] = String(key || '').split('|')
 return getPayrollCutoffPeriodFromParts(yearMonth, type || '11-25')
}

function getCurrentDTRCutoffKey(todayDate = getTodayDate()) {
 const date = parseLocalDate(todayDate)
 if (!date) return `${String(todayDate).slice(0, 7)}|11-25`
 const y = date.getFullYear()
 const m = date.getMonth() + 1
 const d = date.getDate()
 if (d >= 11 && d <= 25) return `${yearMonthFromParts(y, m)}|11-25`
 if (d >= 26) return `${yearMonthFromParts(y, m)}|26-10`
 return `${shiftYearMonth(yearMonthFromParts(y, m), -1)}|26-10`
}

function getPreviousDTRCutoffKey(key) {
 const [yearMonth, type] = String(key || '').split('|')
 if (type === '11-25') return `${shiftYearMonth(yearMonth, -1)}|26-10`
 return `${yearMonth}|11-25`
}

function getDTRCutoffOptions(count = 36, todayDate = getTodayDate()) {
 const options = []
 let key = getCurrentDTRCutoffKey(todayDate)
 for (let i = 0; i < count; i++) {
  const period = getDTRCutoffPeriodFromKey(key)
  if (period) options.push(period)
  key = getPreviousDTRCutoffKey(key)
 }
 return options
}

function formatDateForDisplay(dateStr) {
 const date = parseLocalDate(dateStr)
 if (!date) return dateStr || ''
 return date.toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' })
}

function mergeDTRDayLogs(dayLogs = []) {
 const logs = (dayLogs || []).filter(Boolean)
 if (!logs.length) return null
 const hasAbsent = logs.some(l => l.status === 'Absent')
 const timeInLogs = logs.filter(l => l.time_in)
 const timeOutLogs = logs.filter(l => l.time_out)
 const earliestIn = timeInLogs.map(l => l.time_in).sort()[0] || ''
 const latestOut = timeOutLogs.map(l => l.time_out).sort().slice(-1)[0] || ''
 const approvedOT = logs.filter(l => l.overtime_approved === true).reduce((sum,l)=>sum+safeNum(l.overtime_minutes,0),0)
 const lateMinutes = logs.reduce((sum,l)=>sum+safeNum(l.late_minutes,0),0)
 const breakMinutes = logs.reduce((sum,l)=>sum+safeNum(l.total_break_minutes,0),0)
 const status = hasAbsent? 'Absent': lateMinutes > 0? 'Late': earliestIn? 'Present': (logs[0]?.status || '')
 return {
  ...logs[0],
  time_in:earliestIn,
  time_out:latestOut,
  late_minutes:lateMinutes,
  total_break_minutes:breakMinutes,
  overtime_minutes:approvedOT,
  overtime_approved:approvedOT > 0,
  status,
  _logs:logs,
  duplicateCount:logs.length
 }
}

function groupDTRLogsByDate(logs = []) {
 const grouped = {}
 ;(logs || []).forEach(log => {
  const key = String(log.attendance_date || '').slice(0, 10)
  if (!key) return
  if (!grouped[key]) grouped[key] = []
  grouped[key].push(log)
 })
 return grouped
}

function getLeaveOverlapDays(leave, periodStart, periodEnd) {
 const start = parseLocalDate(leave?.leave_start)
 const end = parseLocalDate(leave?.leave_end)
 const pStart = parseLocalDate(periodStart)
 const pEnd = parseLocalDate(periodEnd)
 if (!start ||!end ||!pStart ||!pEnd) return 0
 const overlapStart = start > pStart? start: pStart
 const overlapEnd = end < pEnd? end: pEnd
 if (overlapEnd < overlapStart) return 0
 return daysInclusive(formatDateLocal(overlapStart), formatDateLocal(overlapEnd))
}


function getAttendanceDateTime(attendanceDate, timeValue, addDay = false) {
 const base = parseLocalDate(attendanceDate)
 if (!base ||!timeValue) return null
 const [h, m, s] = String(timeValue).split(':').map(Number)
 base.setHours(Number(h) || 0, Number(m) || 0, Number(s) || 0, 0)
 if (addDay) base.setDate(base.getDate() + 1)
 return base
}

function getOpenShiftHours(log, asOf = new Date()) {
 if (!log?.attendance_date ||!log?.time_in) return 0
 const start = getAttendanceDateTime(log.attendance_date, log.time_in)
 if (!start) return 0
 return Math.max(0, (asOf.getTime() - start.getTime()) / (1000 * 60 * 60))
}

function isOpenAttendanceLogInDutyWindow(log, asOf = new Date(), maxHours = 36) {
 if (!log?.time_in || log?.time_out) return false
 const hours = getOpenShiftHours(log, asOf)
 return hours >= 0 && hours <= maxHours
}

function isTimedOutOnDate(log, targetDate) {
 if (!log?.time_in ||!log?.time_out ||!targetDate) return false

 // Normal same-day logs use the attendance date.
 if (String(log.attendance_date || '').slice(0, 10) === targetDate) return true

 // Overnight logs are saved under the shift start date, so a 10PM-6AM shift
 // that timed out after midnight should count as timed out on the next day.
 const inM = minutesFromTime(log.time_in)
 const outM = minutesFromTime(log.time_out)
 const crossedMidnight = outM < inM
 if (!crossedMidnight) return false

 const outDate = parseLocalDate(log.attendance_date)
 if (!outDate) return false
 outDate.setDate(outDate.getDate() + 1)
 return formatDateLocal(outDate) === targetDate
}

function getCurrentSILCycle(hireDate, asOf = new Date()) {
 const hire = parseLocalDate(hireDate)
 const todayDate = parseLocalDate(formatDateLocal(asOf))
 if (!hire ||!todayDate) return null

 let years = todayDate.getFullYear() - hire.getFullYear()
 let anniversary = addYearsLocal(hire, years)

 if (anniversary > todayDate) {
 years -= 1
 anniversary = addYearsLocal(hire, years)
 }

 if (years < 1) return null

 const cycleEnd = addYearsLocal(anniversary, 1)
 cycleEnd.setDate(cycleEnd.getDate() - 1)

 return {
 years,
 start: formatDateLocal(anniversary),
 end: formatDateLocal(cycleEnd)
 }
}

function getPreviousSILCycle(cycle) {
 if (!cycle || safeNum(cycle.years, 0) <= 1) return null
 const currentStart = parseLocalDate(cycle.start)
 if (!currentStart) return null

 const previousStart = addYearsLocal(currentStart, -1)
 const previousEnd = new Date(currentStart)
 previousEnd.setDate(previousEnd.getDate() - 1)

 return {
 years: safeNum(cycle.years, 0) - 1,
 start: formatDateLocal(previousStart),
 end: formatDateLocal(previousEnd)
 }
}

function hasOneYearService(hireDate, asOf = new Date()) {
 return!!getCurrentSILCycle(hireDate, asOf)
}

function normalizeLeaveType(type) {
 const t = String(type || '').trim().toLowerCase()
 if (t === 'sil' || t.includes('service incentive')) return 'SIL'
 if (t.includes('unpaid') || t.includes('without pay') || t.includes('lwop')) return 'Unpaid Leave'
 return type || 'Unpaid Leave'
}

function isPaidLeaveRecord(leave) {
 return leave?.is_paid === true || normalizeLeaveType(leave?.leave_type) === 'SIL'
}

function getLeaveDisplayName(type) {
 return normalizeLeaveType(type) === 'SIL'? 'Service Incentive Leave (SIL)': 'Unpaid Leave / Leave Without Pay'
}

function getEmployeeLeaveInfo(emp) {
 const eligible = hasOneYearService(emp?.hire_date)
 const silBalance = safeNum(emp?.sil_balance, 0)
 const canFileSIL = eligible && silBalance > 0

 return {
 eligible,
 silBalance,
 type: canFileSIL? 'SIL': 'Unpaid Leave',
 isPaid: canFileSIL,
 buttonLabel: canFileSIL? 'File SIL': 'File Leave',
 title: canFileSIL? 'File SIL Request': 'File Leave Request',
 label: canFileSIL? 'Service Incentive Leave (SIL) Paid': 'Unpaid Leave / Leave Without Pay',
 note: canFileSIL
? `Remaining SIL: ${silBalance} day(s). Approved SIL is paid.`
: eligible
? 'You are SIL-qualified, but you have no SIL balance left. This request will be unpaid.'
: 'SIL becomes available after 1 year of service. This request will be unpaid.'
 }
}


const PAYROLL_COST_TYPES = [
 { value:'auto', label:'Auto classify from department / position', shortLabel:'Auto', bucket:'auto' },
 { value:'production_cogs', label:'Production Labor / COGS', shortLabel:'Production COGS', bucket:'cogs' },
 { value:'admin_expense', label:'Admin Payroll Expense', shortLabel:'Admin Expense', bucket:'expense' },
 { value:'sales_expense', label:'Sales / Store Payroll Expense', shortLabel:'Sales Expense', bucket:'expense' },
 { value:'delivery_expense', label:'Delivery / Dispatch Payroll Expense', shortLabel:'Delivery Expense', bucket:'expense' },
 { value:'management_expense', label:'Management Payroll Expense', shortLabel:'Management Expense', bucket:'expense' },
 { value:'operating_expense', label:'Other Operating Payroll Expense', shortLabel:'Operating Expense', bucket:'expense' }
]

function normalizePayrollCostType(value) {
 const raw = String(value || '').trim().toLowerCase()
 const found = PAYROLL_COST_TYPES.find(t => t.value === raw)
 return found? found.value: 'auto'
}

function getPayrollCostTypeInfo(value) {
 const key = normalizePayrollCostType(value)
 return PAYROLL_COST_TYPES.find(t => t.value === key) || PAYROLL_COST_TYPES[0]
}

function inferPayrollCostType(emp = {}) {
 const text = `${emp.department || ''} ${emp.position || ''} ${emp.full_name || ''}`.toLowerCase()
 if (/production|kitchen|baker|bakery|dough|mixer|mixing|fry|fryman|fryer|cutter|glazer|finisher|finishing|packer|packing|quality|qc/.test(text)) return 'production_cogs'
 if (/delivery|driver|dispatch|dispatcher|logistics|rider/.test(text)) return 'delivery_expense'
 if (/cashier|sales|seller|saleslady|rolling|cart|store|counter|service crew|crew/.test(text)) return 'sales_expense'
 if (/owner|manager|management|supervisor/.test(text)) return 'management_expense'
 if (/admin|office|hr|payroll|accounting|bookkeeper|finance/.test(text)) return 'admin_expense'
 return 'operating_expense'
}

function getEmployeePayrollCostType(emp = {}) {
 const saved = normalizePayrollCostType(emp.payroll_cost_type)
 return saved === 'auto'? inferPayrollCostType(emp): saved
}

function isProductionPayrollCostType(value) {
 return normalizePayrollCostType(value) === 'production_cogs'
}

function isReleasedPayrollRecord(record = {}) {
 return record.payroll_approved === true || !!record.approved_at
}

function normalizePayrollAcknowledgement(value) {
 return String(value || '').trim().toLowerCase()
}

function normalizePayrollStatus(value) {
 return String(value || '').trim().toLowerCase()
}

function isDraftPayrollRecord(record = {}) {
 const ack = normalizePayrollAcknowledgement(record.employee_acknowledgement)
 const status = normalizePayrollStatus(record.payroll_status)
 return ack === 'draft' || status === 'draft'
}

function isPayrollSentForEmployeeReview(record = {}) {
 if (isReleasedPayrollRecord(record)) return true
 const ack = normalizePayrollAcknowledgement(record.employee_acknowledgement)
 const status = normalizePayrollStatus(record.payroll_status)
 return !!record.review_sent_at || ['pending','agreed','disputed','auto-acknowledged'].includes(ack) || ['under_review','released','approved'].includes(status)
}

function getPayrollReviewStatusText(record = {}) {
 if (isReleasedPayrollRecord(record)) return 'Released'
 if (isDraftPayrollRecord(record)) return 'Draft - admin only'
 if (normalizePayrollAcknowledgement(record.employeeAcknowledgement || record.employee_acknowledgement) === 'disputed') return 'Disputed'
 if (normalizePayrollAcknowledgement(record.employeeAcknowledgement || record.employee_acknowledgement) === 'agreed') return 'Agreed'
 if (isPayrollSentForEmployeeReview(record)) return 'Sent for employee review'
 return 'Draft - admin only'
}

function getPayslipDisputeKey(dispute = {}) {
 const recordId = String(dispute.payroll_record_id || '').trim()
 if (recordId) return `record:${recordId}`
 return [
  dispute.employee_id || dispute.employee_code || dispute.employee_name || '',
  dispute.payroll_start || '',
  dispute.payroll_end || '',
  dispute.reason || ''
 ].map(v=>String(v).trim().toLowerCase()).join('|')
}

function dedupePayslipDisputes(rows = []) {
 const byKey = new Map()
 ;(rows || []).forEach(row => {
  const key = getPayslipDisputeKey(row)
  const existing = byKey.get(key)
  if (!existing) {
   byKey.set(key, { ...row, duplicate_count:0, duplicate_ids:[] })
   return
  }
  const rowTime = new Date(row.created_at || 0).getTime() || 0
  const existingTime = new Date(existing.created_at || 0).getTime() || 0
  if (rowTime > existingTime) {
   byKey.set(key, { ...row, duplicate_count:safeNum(existing.duplicate_count,0) + 1, duplicate_ids:[...(existing.duplicate_ids || []), existing.id, ...(row.duplicate_ids || [])].filter(Boolean) })
  } else {
   existing.duplicate_count = safeNum(existing.duplicate_count,0) + 1
   existing.duplicate_ids = [...(existing.duplicate_ids || []), row.id].filter(Boolean)
  }
 })
 return Array.from(byKey.values()).sort((a,b)=>String(b.created_at || '').localeCompare(String(a.created_at || '')))
}

function isMissingPayrollWorkflowColumnError(error) {
 const msg = String(error?.message || error || '').toLowerCase()
 return msg.includes('payroll_status') || msg.includes('employee_acknowledgement') || msg.includes('review_sent_at') || msg.includes('review_sent_by') || msg.includes('payslip_serial') || msg.includes('undertime_deduction') || msg.includes('late_deduction') || msg.includes('worked_basic_pay') || msg.includes('total_worked_minutes') || msg.includes('regular_paid_minutes') || msg.includes('paid_leave_pay') || msg.includes('paid_leave_days') || msg.includes('unpaid_leave_days') || msg.includes('absent_days') || msg.includes('night_diff_minutes') || msg.includes('overtime_minutes') || msg.includes('requested_cash_advance_deduction') || msg.includes('deferred_cash_advance_deduction') || msg.includes('non_ca_deduction_overflow') || (msg.includes('schema cache') && msg.includes('payroll_records')) || (msg.includes('could not find') && msg.includes('payroll_records'))
}

function isMissingCashAdvanceDetailColumnError(error) {
 const msg = String(error?.message || error || '').toLowerCase()
 return msg.includes('approved_at') || msg.includes('approved_by') || msg.includes('disapproved_at') || msg.includes('processed_at') || msg.includes('processed_by') || msg.includes('ca_ledger_id') || msg.includes('source_request_id') || msg.includes('cash_advance_request_id') || msg.includes('request_installments_total') || msg.includes('request_per_payroll_deduction') || msg.includes('column') || msg.includes('schema cache') || msg.includes('could not find')
}

function formatDateTimeForAdmin(value) {
 if (!value) return 'Not recorded'
 try {
  const d = new Date(value)
  if (Number.isNaN(d.getTime())) return String(value)
  return d.toLocaleString('en-PH', { year:'numeric', month:'short', day:'2-digit', hour:'2-digit', minute:'2-digit' })
 } catch(e) { return String(value) }
}

function getCAFiledDate(req = {}) {
 return req.created_at || req.filed_at || req.request_date || req.advance_date || ''
}

function getCAApprovedDate(req = {}, ledger = null) {
 return req.approved_at || req.processed_at || ledger?.approved_at || ledger?.created_at || ledger?.advance_date || ''
}

function getCAProcessedBy(req = {}, ledger = null) {
 return req.approved_by || req.processed_by || ledger?.approved_by || ledger?.created_by || ledger?.recorded_by || 'Admin'
}

function getCAInstallmentInfo(ca = {}, req = {}) {
 const total = Math.max(0, safeNum(ca.installments_total ?? req.request_installments_total ?? req.installments_total, 0))
 const remaining = Math.max(0, safeNum(ca.installments_remaining ?? req.installments_remaining, 0))
 const completed = total > 0 ? Math.max(0, total - remaining) : 0
 const perPayroll = safeNum(ca.per_payroll_deduction ?? req.request_per_payroll_deduction ?? req.per_payroll_deduction, 0)
 return { total, remaining, completed, perPayroll }
}

function getCashAdvanceStatusColor(status) {
 const s = String(status || '').toLowerCase()
 if (s.includes('paid') || s === 'approved') return 'green'
 if (s.includes('disapproved') || s.includes('rejected')) return 'red'
 if (s.includes('pending')) return 'orange'
 return 'gray'
}



function getEmployeeLookupForPayroll(employeeRows = []) {
 const lookup = {}
 ;(employeeRows || []).forEach(emp => {
  if (!emp) return
  if (emp.id) lookup[`id:${emp.id}`] = emp
  if (emp.employee_code) lookup[`code:${String(emp.employee_code).toLowerCase()}`] = emp
  if (emp.full_name) lookup[`name:${String(emp.full_name).toLowerCase()}`] = emp
 })
 return lookup
}

function findPayrollEmployeeForRecord(record = {}, lookup = {}) {
 return lookup[`id:${record.employee_id}`] || lookup[`code:${String(record.employee_code || '').toLowerCase()}`] || lookup[`name:${String(record.employee_name || '').toLowerCase()}`] || {}
}

function classifyPayrollRecords(records = [], employeeRows = [], options = {}) {
 const includeUnreleased = options.includeUnreleased === true
 const lookup = getEmployeeLookupForPayroll(employeeRows)
 const byType = {}
 PAYROLL_COST_TYPES.forEach(t => { if (t.value !== 'auto') byType[t.value] = { ...t, amount:0, count:0 } })
 let productionLaborCOGS = 0
 let operatingPayrollExpense = 0
 let totalPayroll = 0
 let releasedCount = 0
 const rows = []
 ;(records || []).forEach(record => {
  if (!includeUnreleased && !isReleasedPayrollRecord(record)) return
  const emp = findPayrollEmployeeForRecord(record, lookup)
  const recordType = normalizePayrollCostType(record.payroll_cost_type)
  const type = recordType !== 'auto'? recordType: getEmployeePayrollCostType(emp)
  const info = getPayrollCostTypeInfo(type)
  const amount = safeNum(record.total_earnings, 0)
  totalPayroll += amount
  releasedCount += 1
  if (!byType[type]) byType[type] = { ...info, amount:0, count:0 }
  byType[type].amount += amount
  byType[type].count += 1
  if (isProductionPayrollCostType(type)) productionLaborCOGS += amount
  else operatingPayrollExpense += amount
  rows.push({
   id:record.id,
   employee_id:record.employee_id,
   employee_code:record.employee_code,
   employee_name:record.employee_name || emp.full_name || '',
   payroll_start:record.payroll_start,
   payroll_end:record.payroll_end,
   amount,
   payroll_cost_type:type,
   payroll_cost_label:info.shortLabel || info.label,
   bucket:info.bucket,
   released:isReleasedPayrollRecord(record)
  })
 })
 return {
  productionLaborCOGS,
  operatingPayrollExpense,
  totalPayroll,
  releasedCount,
  byType:Object.values(byType).filter(t => safeNum(t.amount, 0) > 0),
  rows
 }
}

function isMissingPayrollCostColumnError(error) {
 const msg = String(error?.message || error || '').toLowerCase()
 return msg.includes('payroll_cost_type') || msg.includes('payroll_cost_label') || msg.includes('column') && msg.includes('cost')
}


function normalizeProductCostKey(value) {
 return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '').trim()
}

function getProductionReportActualQty(item = {}) {
 return safeNum(item.actual_qty ?? item.actual_quantity ?? item.quantity ?? item.pieces ?? item.produced_qty ?? item.total_produced, 0)
}

function getProductionReportForecastQty(item = {}) {
 return safeNum(item.forecast_qty ?? item.expected_quantity ?? item.default_quantity ?? item.standard_quantity ?? item.forecast_quantity, 0)
}

function getRecipeCostPerPiece(recipe = {}) {
 const direct = safeNum(recipe.cost_per_piece ?? recipe.recipe_cost_per_piece ?? recipe.standard_cost_per_piece, 0)
 if (direct > 0) return moneyRound(direct)
 const batchCost = safeNum(recipe.batch_cost ?? recipe.total_cost ?? recipe.estimated_batch_cost, 0)
 const yieldPieces = safeNum(recipe.batch_yield_pieces ?? recipe.yield_pieces ?? recipe.batch_yield, 0)
 return batchCost > 0 && yieldPieces > 0 ? moneyRound(batchCost / yieldPieces) : 0
}

function buildRecipeCostLookup(recipeRows = []) {
 const lookup = { byVariant:{}, byName:{}, rows:[] }
 const statusRank = status => {
  const s = String(status || '').toLowerCase()
  if (s === 'active' || s === 'approved') return 0
  if (s === 'test' || s === 'draft') return 1
  return 2
 }
 const rows = (recipeRows || [])
 .map(recipe => ({ ...recipe, _costPerPiece:getRecipeCostPerPiece(recipe), _statusRank:statusRank(recipe.status), _date:String(recipe.updated_at || recipe.created_at || '') }))
 .filter(recipe => safeNum(recipe._costPerPiece, 0) > 0)
 .sort((a,b)=>(a._statusRank-b._statusRank) || String(b._date).localeCompare(String(a._date)))
 rows.forEach(recipe => {
  const info = {
   recipe_id:recipe.id || '',
   product_name:recipe.product_name || recipe.name || '',
   recipe_code:recipe.recipe_code || '',
   costPerPiece:moneyRound(recipe._costPerPiece),
   status:recipe.status || '',
   source:`Recipe Vault${recipe.product_name? ` - ${recipe.product_name}`:''}`
  }
  const variantKey = recipe.linked_variant_id? String(recipe.linked_variant_id): ''
  if (variantKey && !lookup.byVariant[variantKey]) lookup.byVariant[variantKey] = info
  ;[recipe.product_name, recipe.name, recipe.variant_name, recipe.recipe_code].forEach(name => {
   const key = normalizeProductCostKey(name)
   if (key && !lookup.byName[key]) lookup.byName[key] = info
  })
  lookup.rows.push(info)
 })
 return lookup
}

function getProductCostInfo(item = {}, lookup = {}) {
 const variantId = item.variant_id || item.linked_variant_id || item.product_variant_id || ''
 if (variantId && lookup.byVariant?.[String(variantId)]) return lookup.byVariant[String(variantId)]
 const names = [item.variant_name, item.product_name, item.item_name, item.name, item.recipe_code]
 for (const name of names) {
  const key = normalizeProductCostKey(name)
  if (key && lookup.byName?.[key]) return lookup.byName[key]
 }
 return null
}

function addCOGSProductRow(map, item = {}, qty = 0, revenue = 0, lookup = {}, source = '') {
 const name = item.variant_name || item.product_name || item.item_name || item.name || 'Unassigned Product'
 const key = normalizeProductCostKey(name) || name
 if (!map[key]) map[key] = { key, name, qty:0, revenue:0, returnsQty:0, returnsAmount:0, cogs:0, missingCostQty:0, costPerPiece:0, sourceSet:new Set() }
 const row = map[key]
 const cleanQty = safeNum(qty, 0)
 const cleanRevenue = safeNum(revenue, 0)
 row.qty += cleanQty
 row.revenue += cleanRevenue
 if (source) row.sourceSet.add(source)
 const costInfo = getProductCostInfo(item, lookup)
 if (costInfo?.costPerPiece > 0 && cleanQty > 0) {
  row.costPerPiece = costInfo.costPerPiece
  row.cogs = moneyRound(row.cogs + cleanQty * costInfo.costPerPiece)
  row.cogsSource = costInfo.source
 } else if (cleanQty > 0) {
  row.missingCostQty += cleanQty
 }
 return row
}

function calculateSoldProductCOGS({ dailySalesRows = [], invoices = [], returnItemMap = {}, recipeRows = [] } = {}) {
 const lookup = buildRecipeCostLookup(recipeRows)
 const productMap = {}
 ;(dailySalesRows || []).forEach(sale => {
  const items = Array.isArray(sale.daily_sales_items) ? sale.daily_sales_items : []
  if (items.length) {
   items.forEach(item => {
    const qty = safeNum(item.quantity ?? item.qty ?? item.sold_qty, 0)
    const revenue = safeNum(item.total_price ?? item.total_amount ?? item.total_revenue, qty * safeNum(item.unit_price ?? item.selling_price, 0))
    addCOGSProductRow(productMap, item, qty, revenue, lookup, item.channel || sale.channel || 'Daily Sales')
   })
  } else {
   const qty = safeNum(sale.quantity ?? sale.qty ?? sale.sold_qty, 0)
   const name = sale.variant_name || sale.product_name || sale.item_name || sale.product || ''
   if (name && qty > 0) {
    const revenue = safeNum(sale.total_price ?? sale.total_amount ?? sale.total_revenue ?? sale.amount, qty * safeNum(sale.unit_price ?? sale.selling_price, 0))
    addCOGSProductRow(productMap, sale, qty, revenue, lookup, sale.channel || 'Daily Sales')
   }
  }
 })
 ;(invoices || []).forEach(inv => {
  ;(inv.delivery_invoice_items || []).forEach(item => {
   const qty = safeNum(item.quantity ?? item.qty ?? item.delivered_qty ?? item.actual_quantity, 0)
   const revenue = safeNum(item.total_price ?? item.total_amount ?? item.subtotal, qty * safeNum(item.reseller_price ?? item.unit_price ?? item.price, 0))
   addCOGSProductRow(productMap, item, qty, revenue, lookup, 'Reseller Invoice')
  })
 })
 Object.values(returnItemMap || {}).forEach(ret => {
  const key = normalizeProductCostKey(ret.name)
  const row = productMap[key]
  const qty = safeNum(ret.qty, 0)
  if (row) {
   row.returnsQty += qty
   row.returnsAmount += safeNum(ret.amount, 0)
   const returnedCOGS = row.costPerPiece > 0 ? moneyRound(qty * row.costPerPiece) : 0
   row.cogs = moneyRound(Math.max(0, row.cogs - returnedCOGS))
   row.qty = Math.max(0, row.qty - qty)
   row.revenue = Math.max(0, row.revenue - safeNum(ret.amount, 0))
  }
 })
 const productRows = Object.values(productMap).map(row => ({
  ...row,
  source:Array.from(row.sourceSet || []).join(' + '),
  cogs:moneyRound(row.cogs),
  grossProfit:moneyRound(safeNum(row.revenue,0) - safeNum(row.cogs,0)),
  marginPct:safeNum(row.revenue,0) > 0? moneyRound(((safeNum(row.revenue,0)-safeNum(row.cogs,0))/safeNum(row.revenue,0))*100):0,
  foodCostPct:safeNum(row.revenue,0) > 0? moneyRound((safeNum(row.cogs,0)/safeNum(row.revenue,0))*100):0
 })).sort((a,b)=>safeNum(b.cogs,0)-safeNum(a.cogs,0))
 const totalCOGS = productRows.reduce((sum,row)=>sum+safeNum(row.cogs,0),0)
 const totalQty = productRows.reduce((sum,row)=>sum+safeNum(row.qty,0),0)
 const missingCostQty = productRows.reduce((sum,row)=>sum+safeNum(row.missingCostQty,0),0)
 return { totalCOGS:moneyRound(totalCOGS), totalQty, missingCostQty, productRows, lookup, source:totalCOGS > 0? 'Sold products × Recipe Vault cost per piece':'No sold-product recipe cost' }
}

function calculateProductionReportCOGS(productionReportsRows = [], recipeRowsOrLookup = []) {
 const lookup = Array.isArray(recipeRowsOrLookup)? buildRecipeCostLookup(recipeRowsOrLookup): recipeRowsOrLookup
 const productMap = {}
 ;(productionReportsRows || []).forEach(report => {
  ;(report.production_report_items || []).forEach(item => {
   const qty = getProductionReportActualQty(item)
   const costInfo = getProductCostInfo(item, lookup)
   const storedCost = safeNum(item.estimated_cogs ?? item.total_cogs ?? item.material_cogs, 0)
   const itemCost = storedCost > 0 ? storedCost : (costInfo?.costPerPiece > 0 ? qty * costInfo.costPerPiece : 0)
   const name = item.variant_name || item.product_name || item.item_name || 'Unassigned Product'
   const key = normalizeProductCostKey(name) || name
   if (!productMap[key]) productMap[key] = { key, name, qty:0, cogs:0, missingCostQty:0, costPerPiece:costInfo?.costPerPiece || 0, sourceSet:new Set() }
   productMap[key].qty += qty
   productMap[key].cogs = moneyRound(productMap[key].cogs + itemCost)
   if (costInfo?.costPerPiece > 0 || storedCost > 0) productMap[key].sourceSet.add(storedCost > 0? 'Production report saved cost':'Production report × Recipe Vault')
   else if (qty > 0) productMap[key].missingCostQty += qty
  })
 })
 const productRows = Object.values(productMap).map(row => ({ ...row, source:Array.from(row.sourceSet || []).join(' + '), cogs:moneyRound(row.cogs) })).sort((a,b)=>safeNum(b.cogs,0)-safeNum(a.cogs,0))
 const totalCOGS = productRows.reduce((sum,row)=>sum+safeNum(row.cogs,0),0)
 const totalQty = productRows.reduce((sum,row)=>sum+safeNum(row.qty,0),0)
 const missingCostQty = productRows.reduce((sum,row)=>sum+safeNum(row.missingCostQty,0),0)
 return { totalCOGS:moneyRound(totalCOGS), totalQty, missingCostQty, productRows, lookup, source:totalCOGS > 0? 'Production report actual qty × Recipe Vault cost per piece':'No production report recipe cost' }
}

function chooseDirectProductCOGS({ soldProductCOGS = 0, productionReportCOGS = 0, productionLogCOGS = 0 } = {}) {
 const sold = safeNum(soldProductCOGS, 0)
 const report = safeNum(productionReportCOGS, 0)
 const logs = safeNum(productionLogCOGS, 0)
 if (sold > 0) return { amount:moneyRound(sold), source:'Sold products × Recipe Vault cost per piece', method:'sold_recipe' }
 if (report > 0) return { amount:moneyRound(report), source:'Production report actual qty × Recipe Vault cost per piece', method:'production_report_recipe' }
 if (logs > 0) return { amount:moneyRound(logs), source:'Production logs total cost', method:'production_logs' }
 return { amount:0, source:'No product COGS source yet', method:'none' }
}


// Passkey / Fingerprint Login Helpers 
// Uses WebAuthn. The app never receives or stores the actual fingerprint.
function browserSupportsPasskeys() {
 return typeof window!== 'undefined' &&!!window.PublicKeyCredential &&!!navigator.credentials
}

function bufferToBase64URL(buffer) {
 const bytes = buffer instanceof Uint8Array? buffer: new Uint8Array(buffer)
 let binary = ''
 for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i])
 return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '')
}

function base64URLToBuffer(base64url) {
 const base64 = String(base64url || '').replace(/-/g, '+').replace(/_/g, '/')
 const pad = '='.repeat((4 - (base64.length % 4)) % 4)
 const binary = atob(base64 + pad)
 const bytes = new Uint8Array(binary.length)
 for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i)
 return bytes.buffer
}

function preparePublicKeyCreationOptions(options) {
 const publicKey = {...options }
 publicKey.challenge = base64URLToBuffer(publicKey.challenge)
 if (publicKey.user?.id) publicKey.user = {...publicKey.user, id: base64URLToBuffer(publicKey.user.id) }
 if (Array.isArray(publicKey.excludeCredentials)) {
 publicKey.excludeCredentials = publicKey.excludeCredentials.map(c => ({...c, id: base64URLToBuffer(c.id) }))
 }
 return publicKey
}

function preparePublicKeyRequestOptions(options) {
 const publicKey = {...options }
 publicKey.challenge = base64URLToBuffer(publicKey.challenge)
 if (Array.isArray(publicKey.allowCredentials)) {
 publicKey.allowCredentials = publicKey.allowCredentials.map(c => ({...c, id: base64URLToBuffer(c.id) }))
 }
 return publicKey
}

function publicKeyCredentialToJSON(credential) {
 if (!credential) return null
 const response = credential.response || {}
 const json = {
 id: credential.id,
 rawId: bufferToBase64URL(credential.rawId),
 type: credential.type,
 clientExtensionResults: credential.getClientExtensionResults? credential.getClientExtensionResults(): {},
 authenticatorAttachment: credential.authenticatorAttachment || undefined,
 response: {}
 }

 if (response.clientDataJSON) json.response.clientDataJSON = bufferToBase64URL(response.clientDataJSON)
 if (response.attestationObject) json.response.attestationObject = bufferToBase64URL(response.attestationObject)
 if (response.authenticatorData) json.response.authenticatorData = bufferToBase64URL(response.authenticatorData)
 if (response.signature) json.response.signature = bufferToBase64URL(response.signature)
 if (response.userHandle) json.response.userHandle = bufferToBase64URL(response.userHandle)

 const transports = typeof response.getTransports === 'function'? response.getTransports(): undefined
 if (transports) json.response.transports = transports

 return json
}


