 function buildDeliveryInvoicePrintPage(invoice, pageClass = '') {
    const items = Array.isArray(invoice.delivery_invoice_items) ? invoice.delivery_invoice_items : [];
    const reseller = resellers.find(r => String(r.id) === String(invoice.reseller_id));
    const resellerAccount = resellerAccounts.find(a => String(a.id) === String(reseller?.reseller_account_id || invoice.reseller_account_id || ''));

    const cleanText = value => String(value || '').trim();
    const normalize = value => cleanText(value).toLowerCase().replace(/[^a-z0-9]/g, '');
    const escapeHtml = value => cleanText(value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');

    const peso = value => {
      const amount = safeNum(value, 0).toLocaleString('en-PH', { minimumFractionDigits:2, maximumFractionDigits:2 });
      return '\u20B1' + amount;
    };

    const formatInvoiceDate = value => {
      const raw = cleanText(value);
      if (!raw) return '';
      const datePart = raw.slice(0, 10);
      const parts = datePart.split('-');
      if (parts.length === 3) return parts[1] + ' / ' + parts[2] + ' / ' + parts[0];
      return raw;
    };

    const customerType = cleanText(invoice.customer_type || (invoice.reseller_id ? 'reseller' : 'non_reseller')).toLowerCase();
    const resellerName = customerType === 'non_reseller'
      ? [invoice.customer_name, invoice.reseller_name, invoice.customer_contact].map(cleanText).find(Boolean) || ''
      : [
        reseller?.contact_person,
        resellerAccount?.owner_name,
        resellerAccount?.account_name,
        invoice.reseller_contact_person,
        invoice.reseller_owner_name,
        invoice.customer_name,
        invoice.reseller_name,
        reseller?.name
      ].map(cleanText).find(Boolean) || '';

    const resellerAddress = customerType === 'non_reseller'
      ? [invoice.customer_address, invoice.address, invoice.customer_contact].map(cleanText).find(Boolean) || ''
      : [
        reseller?.address,
        invoice.customer_address,
        invoice.reseller_address,
        invoice.address,
        reseller?.area
      ].map(cleanText).find(Boolean) || '';

    const containerLabel = cleanText(invoice.container_type || 'Crates');
    const preparedBy = '';
    const productionDispatchNote = getInvoiceProductionDispatchNote(invoice);

    const rows = [
      { label:'Choco Balls', aliases:['Choco Balls'] },
      { label:'', aliases:[] },
      { label:'Almond Glitz', aliases:['Almond Glitz'] },
      { label:'Fanfans', aliases:['Fanfans', 'Fan Fans'] },
      { label:'Oreo Dream', aliases:['Oreo Dream'] },
      { label:'Lotus Cloud', aliases:['Lotus Cloud'] },
      { label:'Rings', aliases:['Rings'] },
      { label:'Shells', aliases:['Shells'] },
      { label:'Bav. Midnight', aliases:['Bavarian Midnight', 'Bav. Midnight', 'Bav Midnight'] },
      { label:'Circlets', aliases:['Circlets', 'Glazed Circlets', 'Glaze Circlet'] },
      { label:'Bavarian Bites', aliases:['Bavarian Bites'] },
      { label:'Bavarian Pops', aliases:['Bavarian Pops'] },
      { label:'Strawberry Pops', aliases:['Strawberry Pops'] },
      { label:'Taro Pops', aliases:['Taro Pops'] },
      { label:'Cinnamon Rolls', aliases:['Cinnamon Rolls'] },
      { label:'Biscoreo', aliases:['Biscoreo'] },
      { label:'Choco Lollisticks', aliases:['Choco Lollisticks', 'Choco Lollistick', 'Choco Lollistiks'] }
    ];

    const getQty = item => safeNum(item?.delivered_quantity ?? item?.actual_quantity ?? item?.quantity, 0);
    const getPrice = item => safeNum(item?.reseller_price ?? item?.unit_price ?? item?.price ?? item?.selling_price, 0);
    const getAmount = item => {
      const stored = safeNum(item?.total_price ?? item?.amount ?? item?.line_total, NaN);
      if (Number.isFinite(stored)) return stored;
      return getQty(item) * getPrice(item);
    };

    const findMatchingItems = row => {
      if (!row.label) return [];
      const aliases = row.aliases.map(normalize);
      return items.filter(item => {
        const itemName = normalize(item.variant_name || item.product_name || item.name || '');
        return aliases.some(alias => itemName === alias || itemName.includes(alias) || alias.includes(itemName));
      });
    };

    const productRowsHtml = rows.map(row => {
      if (!row.label) {
        return '<tr class="product-row"><td>&nbsp;</td><td></td><td></td><td></td><td></td></tr>';
      }

      const matched = findMatchingItems(row);
      const qty = matched.reduce((sum, item) => sum + getQty(item), 0);
      const first = matched[0] || null;
      const price = first ? getPrice(first) : 0;
      const amount = matched.reduce((sum, item) => sum + getAmount(item), 0);

      return `<tr class="product-row">
        <td class="product-name">${escapeHtml(row.label)}</td>
        <td class="number-cell">${qty ? qty.toLocaleString('en-PH') : ''}</td>
        <td class="money-cell">${price ? peso(price) : ''}</td>
        <td class="money-cell">${amount ? peso(amount) : ''}</td>
        <td></td>
      </tr>`;
    }).join('');

    const computedTotal = rows.reduce((sum, row) => {
      return sum + findMatchingItems(row).reduce((itemSum, item) => itemSum + getAmount(item), 0);
    }, 0);

    const invoiceTotal = safeNum(invoice.total_amount, computedTotal || 0) || computedTotal;

    return `
      <section class="invoice-page ${pageClass}">
        <table class="invoice-table">
          <colgroup>
            <col style="width:31%;">
            <col style="width:21%;">
            <col style="width:16%;">
            <col style="width:16%;">
            <col style="width:16%;">
          </colgroup>

          <tr class="title-row">
            <td colspan="5">Roma\u2019s Donuts \u2013 Delivery Invoice</td>
          </tr>

          <tr class="field-row">
            <td class="field-label">Date:</td>
            <td class="field-value date-fill" colspan="3">${escapeHtml(formatInvoiceDate(invoice.delivery_date || invoice.invoice_date || ''))}</td>
            <td></td>
          </tr>

          <tr class="field-row">
            <td class="field-label">Customer:</td>
            <td class="field-value customer-fill" colspan="3">${escapeHtml(resellerName)}</td>
            <td></td>
          </tr>

          <tr class="field-row">
            <td class="field-label">Address:</td>
            <td class="field-value address-fill" colspan="3">${escapeHtml(resellerAddress)}</td>
            <td></td>
          </tr>

          <tr class="note-row">
            <td class="note-cell" colspan="5">NOTES:${productionDispatchNote ? ' ' + escapeHtml(productionDispatchNote) : ''}</td>
          </tr>

          <tr class="header-row">
            <th>Product</th>
            <th>Delivered</th>
            <th>Price</th>
            <th>Amount</th>
            <th>Unsold</th>
          </tr>

          ${productRowsHtml}

          <tr class="blank-row"><td></td><td></td><td></td><td></td><td></td></tr>

          <tr class="footer-row">
            <td class="footer-label">${escapeHtml(containerLabel)} Used</td>
            <td class="number-cell">${invoice.crates_used ? escapeHtml(invoice.crates_used) : ''}</td>
            <td></td>
            <td></td>
            <td></td>
          </tr>

          <tr class="footer-row">
            <td class="footer-label">${escapeHtml(containerLabel)} Cover</td>
            <td></td>
            <td class="total-label">TOTAL</td>
            <td class="total-amount">${peso(invoiceTotal)}</td>
            <td></td>
          </tr>

          <tr class="footer-row">
            <td class="footer-label prepared-fill">Prepared by:</td>
            <td class="prepared-fill" colspan="2">${escapeHtml(preparedBy)}</td>
            <td></td>
            <td></td>
          </tr>
        </table>
      </section>`;
  }



 function escapeWordDocText(value) {
   return String(value || '')
     .replace(/&/g, '&amp;')
     .replace(/</g, '&lt;')
     .replace(/>/g, '&gt;')
     .replace(/"/g, '&quot;')
     .replace(/'/g, '&#39;')
 }

 function sanitizeWordFileName(value) {
   const clean = String(value || 'roma-delivery-invoice')
     .replace(/[\\/:*?"<>|]+/g, '-')
     .replace(/\s+/g, '_')
     .replace(/_+/g, '_')
     .replace(/^_+|_+$/g, '')
   return clean.slice(0, 120) || 'roma-delivery-invoice'
 }


  // MASTER DONUT VARIETY ORDER - use this everywhere for uniform display.
  const DONUT_VARIANT_DISPLAY_ORDER = [
    { label:'Choco Balls', aliases:['Choco Balls'] },
    { label:'Matcha Pops', aliases:['Matcha Pops'] },
    { label:'Taro Pops', aliases:['Taro Pops'] },
    { label:'Strawberry Pops', aliases:['Strawberry Pops'] },
    { label:'Bavarian Pops', aliases:['Bavarian Pops'] },
    { label:'Bavarian Bites', aliases:['Bavarian Bites'] },
    { label:'Choco Lollisticks', aliases:['Choco Lollisticks', 'Choco Lollistick', 'Choco Lollistiks'] },
    { label:'Circlets', aliases:['Circlets', 'Glazed Circlets', 'Glaze Circlet'] },
    { label:'Cinnamon Rolls', aliases:['Cinnamon Rolls'] },
    { label:'Rings', aliases:['Rings'] },
    { label:'Shells', aliases:['Shells'] },
    { label:'Bav. Midnight', aliases:['Bavarian Midnight', 'Bav. Midnight', 'Bav Midnight'] },
    { label:'Biscoreo', aliases:['Biscoreo'] },
    { label:'Oreo Dream', aliases:['Oreo Dream'] },
    { label:'Fanfans', aliases:['Fanfans', 'Fan Fans'] },
    { label:'Almond Glitz', aliases:['Almond Glitz'] },
    { label:'Lotus Cloud', aliases:['Lotus Cloud'] }
  ];

  function normalizeDonutVariantName(value) {
    return String(value || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
  }

  const DONUT_VARIANT_ORDER_INDEX = DONUT_VARIANT_DISPLAY_ORDER.reduce((map, row, index) => {
    [row.label, ...(row.aliases || [])].forEach(name => {
      const key = normalizeDonutVariantName(name);
      if (key) map[key] = index;
    });
    return map;
  }, {});

  function getDonutVariantOrderIndex(value) {
    const key = normalizeDonutVariantName(value);
    return Object.prototype.hasOwnProperty.call(DONUT_VARIANT_ORDER_INDEX, key)
      ? DONUT_VARIANT_ORDER_INDEX[key]
      : 9999;
  }

  function compareDonutVariantNamesByGuide(a, b) {
    const ai = getDonutVariantOrderIndex(a);
    const bi = getDonutVariantOrderIndex(b);
    if (ai !== bi) return ai - bi;
    return String(a || '').localeCompare(String(b || ''));
  }

  function compareDonutVariantRowsByGuide(a, b) {
    const an = a?.variant_name || a?.variant || a?.product_name || a?.name || a?.product || '';
    const bn = b?.variant_name || b?.variant || b?.product_name || b?.name || b?.product || '';
    return compareDonutVariantNamesByGuide(an, bn);
  }

  function sortDonutVariantsByGuide(list) {
    return [...(Array.isArray(list) ? list : [])].sort((a, b) =>
      compareDonutVariantNamesByGuide(
        a?.name || a?.variant_name || a?.product_name || '',
        b?.name || b?.variant_name || b?.product_name || ''
      )
    );
  }

  function buildInvoiceProductTemplateFromGuide() {
    return DONUT_VARIANT_DISPLAY_ORDER.map(row => ({
      label: row.label,
      aliases: row.aliases || [row.label]
    }));
  }

 function getDeliveryInvoicePrintData(invoice) {
   const items = Array.isArray(invoice?.delivery_invoice_items) ? invoice.delivery_invoice_items : []
   const reseller = resellers.find(r => String(r.id) === String(invoice?.reseller_id))
   const resellerAccount = resellerAccounts.find(a => String(a.id) === String(reseller?.reseller_account_id || invoice?.reseller_account_id || ''))

   const cleanText = value => String(value || '').trim()
   const normalize = value => cleanText(value).toLowerCase().replace(/[^a-z0-9]/g, '')

   const peso = value => {
     const amount = safeNum(value, 0).toLocaleString('en-PH', { minimumFractionDigits:2, maximumFractionDigits:2 })
     return '\u20B1' + amount
   }

   const formatInvoiceDate = value => {
     const raw = cleanText(value)
     if (!raw) return ''
     const datePart = raw.slice(0, 10)
     const parts = datePart.split('-')
     if (parts.length === 3) return parts[1] + ' / ' + parts[2] + ' / ' + parts[0]
     return raw
   }

   const customerType = cleanText(invoice?.customer_type || (invoice?.reseller_id ? 'reseller' : 'non_reseller')).toLowerCase()
   const customerName = customerType === 'non_reseller'
     ? [invoice?.customer_name, invoice?.reseller_name, invoice?.customer_contact].map(cleanText).find(Boolean) || ''
     : [
       reseller?.contact_person,
       resellerAccount?.owner_name,
       resellerAccount?.account_name,
       invoice?.reseller_contact_person,
       invoice?.reseller_owner_name,
       invoice?.customer_name,
       invoice?.reseller_name,
       reseller?.name
     ].map(cleanText).find(Boolean) || ''

   const customerAddress = customerType === 'non_reseller'
     ? [invoice?.customer_address, invoice?.address, invoice?.customer_contact].map(cleanText).find(Boolean) || ''
     : [
       reseller?.address,
       invoice?.customer_address,
       invoice?.reseller_address,
       invoice?.address,
       reseller?.area
     ].map(cleanText).find(Boolean) || ''

    const productTemplate = buildInvoiceProductTemplateFromGuide()

   const getQty = item => safeNum(item?.delivered_quantity ?? item?.actual_quantity ?? item?.quantity, 0)
   const getPrice = item => safeNum(item?.reseller_price ?? item?.unit_price ?? item?.price ?? item?.selling_price, 0)
   const getAmount = item => {
     const stored = safeNum(item?.total_price ?? item?.amount ?? item?.line_total, NaN)
     if (Number.isFinite(stored)) return stored
     return getQty(item) * getPrice(item)
   }

   const findMatchingItems = row => {
     if (!row.label) return []
     const aliases = row.aliases.map(normalize)
     return items.filter(item => {
       const itemName = normalize(item.variant_name || item.product_name || item.name || '')
       return aliases.some(alias => itemName === alias || itemName.includes(alias) || alias.includes(itemName))
     })
   }

   const productRows = productTemplate.map(row => {
     if (!row.label) return { product:'', delivered:'', price:'', amount:'', unsold:'' }
     const matched = findMatchingItems(row)
     const qty = matched.reduce((sum, item) => sum + getQty(item), 0)
     const first = matched[0] || null
     const price = first ? getPrice(first) : 0
     const amount = matched.reduce((sum, item) => sum + getAmount(item), 0)
     return {
       product: row.label,
       delivered: qty ? qty.toLocaleString('en-PH') : '',
       price: price ? peso(price) : '',
       amount: amount ? peso(amount) : '',
       unsold: ''
     }
   })

   const computedTotal = productTemplate.reduce((sum, row) => {
     return sum + findMatchingItems(row).reduce((itemSum, item) => itemSum + getAmount(item), 0)
   }, 0)
   const invoiceTotal = safeNum(invoice?.total_amount, computedTotal || 0) || computedTotal

   return {
     title:'Roma’s Donuts - Delivery Invoice',
     date:formatInvoiceDate(invoice?.delivery_date || invoice?.invoice_date || ''),
     customerName,
     customerAddress,
     containerLabel:cleanText(invoice?.container_type || 'Crates'),
     cratesUsed:invoice?.crates_used ? cleanText(invoice.crates_used) : '',
     productionDispatchNote:getInvoiceProductionDispatchNote(invoice),
     total:peso(invoiceTotal),
     preparedBy:'',
     productRows
   }
 }

 function wordXmlText(value) {
   return String(value ?? '')
     .replace(/&/g, '&amp;')
     .replace(/</g, '&lt;')
     .replace(/>/g, '&gt;')
     .replace(/"/g, '&quot;')
     .replace(/'/g, '&apos;')
 }

 function wordRun(text, opts = {}) {
   const size = opts.size || 15
   // Use bold as the default for invoice readability on 4x6 thermal/photo paper.
   // Pass bold:false only for intentionally light text.
   const bold = opts.bold === false ? '' : '<w:b/><w:bCs/>'
   const italic = opts.italic ? '<w:i/><w:iCs/>' : ''
   return `<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:sz w:val="${size}"/><w:szCs w:val="${size}"/>${bold}${italic}</w:rPr><w:t xml:space="preserve">${wordXmlText(text)}</w:t></w:r>`
 }

 function wordParagraph(text, opts = {}) {
   const align = opts.align || 'left'
   // A line-height equal to the font size clips bold text in Word print preview.
   // Give each line a small safety allowance while keeping the exact 4x6 table height.
   const size = opts.size || 15
   const line = opts.line || Math.max(205, Math.ceil(size * 13))
   return `<w:p><w:pPr><w:jc w:val="${align}"/><w:spacing w:before="0" w:after="0" w:line="${line}" w:lineRule="exact"/></w:pPr>${wordRun(text, opts)}</w:p>`
 }

 function wordCell(text, opts = {}) {
   const width = safeNum(opts.width, 1000)
   const span = opts.span ? `<w:gridSpan w:val="${opts.span}"/>` : ''
   const shade = opts.shade ? `<w:shd w:fill="${opts.shade}"/>` : ''
   const vAlign = '<w:vAlign w:val="center"/>'
   const cellMargins = '<w:tcMar><w:top w:w="4" w:type="dxa"/><w:left w:w="24" w:type="dxa"/><w:bottom w:w="4" w:type="dxa"/><w:right w:w="24" w:type="dxa"/></w:tcMar>'
   return `<w:tc><w:tcPr><w:tcW w:w="${width}" w:type="dxa"/>${span}${shade}${vAlign}${cellMargins}</w:tcPr>${wordParagraph(text, opts)}</w:tc>`
 }

 function wordRow(cells, height = 320) {
   return `<w:tr><w:trPr><w:trHeight w:val="${height}" w:hRule="exact"/><w:cantSplit/></w:trPr>${cells.join('')}</w:tr>`
 }

 function buildInvoiceDocxTopSpacer(startNewPage = false) {
   // Keeps the invoice title away from Word/printer top clipping while page margin stays 0.
   // For Print All, use pageBreakBefore on this spacer instead of placing a page-break paragraph
   // after each invoice. A trailing page-break paragraph can be forced onto its own sheet,
   // which creates the blank pages seen between invoices in Word print preview.
   const pageBreak = startNewPage ? '<w:pageBreakBefore/>' : ''
   return `<w:p><w:pPr>${pageBreak}<w:spacing w:before="0" w:after="0" w:line="351" w:lineRule="exact"/></w:pPr></w:p>`
 }

 function buildDeliveryInvoiceDocxTable(invoice) {
   const data = getDeliveryInvoicePrintData(invoice)
   // Keep the invoice body at exactly 100mm x 140mm and center it
   // inside the 4x6 inch Word page. 100mm = 5669 twips, 140mm = about 7937 twips.
   const widths = [1750, 1210, 903, 903, 903]
   const full = widths.reduce((sum, w) => sum + w, 0)
   const valueSpan3 = widths[1] + widths[2] + widths[3]

   const rows = []
   rows.push(wordRow([wordCell(data.title, { width:full, span:5, align:'center', bold:true, size:19, line:235 })], 420))
   rows.push(wordRow([
     wordCell('Date:', { width:widths[0], align:'center', bold:true, size:16 }),
     wordCell(data.date, { width:valueSpan3, span:3, align:'left', size:16, shade:'CFE2F3' }),
     wordCell('', { width:widths[4], align:'center', size:15 })
   ], 350))
   rows.push(wordRow([
     wordCell('Customer:', { width:widths[0], align:'center', bold:true, size:16 }),
     wordCell(data.customerName, { width:valueSpan3, span:3, align:'left', size:16, shade:'CFE2F3' }),
     wordCell('', { width:widths[4], align:'center', size:15 })
   ], 350))
   rows.push(wordRow([
     wordCell('Address:', { width:widths[0], align:'center', bold:true, size:16 }),
     wordCell(data.customerAddress, { width:valueSpan3, span:3, align:'left', size:15, shade:'B6D7A8' }),
     wordCell('', { width:widths[4], align:'center', size:15 })
   ], 350))
   rows.push(wordRow([
     wordCell(`NOTES:${data.productionDispatchNote ? ' ' + data.productionDispatchNote : ''}`, { width:full, span:5, align:'left', bold:true, size:14, line:175, shade:'FFF2CC' })
   ], 360))
   rows.push(wordRow([
     wordCell('Product', { width:widths[0], align:'center', bold:true, size:16 }),
     wordCell('Delivered', { width:widths[1], align:'center', bold:true, size:16 }),
     wordCell('Price', { width:widths[2], align:'center', bold:true, size:16 }),
     wordCell('Amount', { width:widths[3], align:'center', bold:true, size:16 }),
     wordCell('Unsold', { width:widths[4], align:'center', bold:true, size:16 })
   ], 350))

   data.productRows.forEach(row => {
     rows.push(wordRow([
       wordCell(row.product, { width:widths[0], align:'center', bold:!!row.product, size:14 }),
       wordCell(row.delivered, { width:widths[1], align:'center', size:15 }),
       wordCell(row.price, { width:widths[2], align:'right', size:14 }),
       wordCell(row.amount, { width:widths[3], align:'right', size:14 }),
       wordCell(row.unsold, { width:widths[4], align:'center', size:15 })
     ], 267))
   })

   rows.push(wordRow(widths.map(w => wordCell('', { width:w, align:'center', size:14 })), 80))
   rows.push(wordRow([
     wordCell(`${data.containerLabel} Used`, { width:widths[0], align:'center', bold:true, italic:true, size:14 }),
     wordCell(data.cratesUsed, { width:widths[1], align:'center', size:15 }),
     wordCell('', { width:widths[2], align:'center', size:15 }),
     wordCell('', { width:widths[3], align:'center', size:15 }),
     wordCell('', { width:widths[4], align:'center', size:15 })
   ], 350))
   rows.push(wordRow([
     wordCell(`${data.containerLabel} Cover`, { width:widths[0], align:'center', bold:true, italic:true, size:14 }),
     wordCell('', { width:widths[1], align:'center', size:15 }),
     wordCell('TOTAL', { width:widths[2], align:'center', bold:true, size:17 }),
     wordCell(data.total, { width:widths[3], align:'right', bold:true, size:17, shade:'D9D9D9' }),
     wordCell('', { width:widths[4], align:'center', size:15 })
   ], 390))
   rows.push(wordRow([
     wordCell('Prepared by:', { width:widths[0], align:'center', bold:true, italic:true, size:14, shade:'B6D7A8' }),
     wordCell(data.preparedBy, { width:widths[1] + widths[2], span:2, align:'left', size:14, shade:'B6D7A8' }),
     wordCell('', { width:widths[3], align:'center', size:15 }),
     wordCell('', { width:widths[4], align:'center', size:15 })
   ], 400))

   return `<w:tbl><w:tblPr><w:tblW w:w="${full}" w:type="dxa"/><w:jc w:val="center"/><w:tblLayout w:type="fixed"/><w:tblLook w:firstRow="0" w:lastRow="0" w:firstColumn="0" w:lastColumn="0" w:noHBand="1" w:noVBand="1"/><w:tblBorders><w:top w:val="single" w:sz="14" w:space="0" w:color="000000"/><w:left w:val="single" w:sz="14" w:space="0" w:color="000000"/><w:bottom w:val="single" w:sz="14" w:space="0" w:color="000000"/><w:right w:val="single" w:sz="14" w:space="0" w:color="000000"/><w:insideH w:val="single" w:sz="10" w:space="0" w:color="000000"/><w:insideV w:val="single" w:sz="10" w:space="0" w:color="000000"/></w:tblBorders><w:tblCellMar><w:top w:w="0" w:type="dxa"/><w:left w:w="0" w:type="dxa"/><w:bottom w:w="0" w:type="dxa"/><w:right w:w="0" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>${widths.map(w => `<w:gridCol w:w="${w}"/>`).join('')}</w:tblGrid>${rows.join('')}</w:tbl>`
 }

 function buildDeliveryInvoicesDocxDocument(invoices) {
   const invoiceList = Array.isArray(invoices) ? invoices : []
   const bodyParts = []
   invoiceList.forEach((invoice, idx) => {
     bodyParts.push(buildInvoiceDocxTopSpacer(idx > 0))
     bodyParts.push(buildDeliveryInvoiceDocxTable(invoice))
   })

   return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:body>${bodyParts.join('')}<w:sectPr><w:pgSz w:w="5760" w:h="8640"/><w:pgMar w:top="0" w:right="0" w:bottom="0" w:left="0" w:header="0" w:footer="0" w:gutter="0"/><w:cols w:space="0"/><w:docGrid w:linePitch="360"/></w:sectPr></w:body></w:document>`
 }

 function createCrc32Table() {
   const table = new Uint32Array(256)
   for (let i = 0; i < 256; i++) {
     let c = i
     for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1)
     table[i] = c >>> 0
   }
   return table
 }

 function crc32Bytes(bytes) {
   const table = createCrc32Table()
   let crc = 0xFFFFFFFF
   for (let i = 0; i < bytes.length; i++) crc = table[(crc ^ bytes[i]) & 0xFF] ^ (crc >>> 8)
   return (crc ^ 0xFFFFFFFF) >>> 0
 }

 function writeUint16LE(array, value) {
   array.push(value & 0xFF, (value >>> 8) & 0xFF)
 }

 function writeUint32LE(array, value) {
   array.push(value & 0xFF, (value >>> 8) & 0xFF, (value >>> 16) & 0xFF, (value >>> 24) & 0xFF)
 }

 function concatUint8Arrays(chunks) {
   const total = chunks.reduce((sum, chunk) => sum + chunk.length, 0)
   const out = new Uint8Array(total)
   let offset = 0
   chunks.forEach(chunk => { out.set(chunk, offset); offset += chunk.length })
   return out
 }

 function createStoredZipBlob(files, mimeType) {
   const encoder = new TextEncoder()
   const localChunks = []
   const centralChunks = []
   let offset = 0
   const now = new Date()
   const dosTime = ((now.getHours() & 0x1F) << 11) | ((now.getMinutes() & 0x3F) << 5) | ((Math.floor(now.getSeconds() / 2)) & 0x1F)
   const dosDate = (((now.getFullYear() - 1980) & 0x7F) << 9) | (((now.getMonth() + 1) & 0x0F) << 5) | (now.getDate() & 0x1F)

   files.forEach(file => {
     const nameBytes = encoder.encode(file.name)
     const dataBytes = typeof file.data === 'string' ? encoder.encode(file.data) : file.data
     const crc = crc32Bytes(dataBytes)
     const local = []
     writeUint32LE(local, 0x04034b50)
     writeUint16LE(local, 20)
     writeUint16LE(local, 0)
     writeUint16LE(local, 0)
     writeUint16LE(local, dosTime)
     writeUint16LE(local, dosDate)
     writeUint32LE(local, crc)
     writeUint32LE(local, dataBytes.length)
     writeUint32LE(local, dataBytes.length)
     writeUint16LE(local, nameBytes.length)
     writeUint16LE(local, 0)
     const localHeader = new Uint8Array([...local, ...nameBytes])
     localChunks.push(localHeader, dataBytes)

     const central = []
     writeUint32LE(central, 0x02014b50)
     writeUint16LE(central, 20)
     writeUint16LE(central, 20)
     writeUint16LE(central, 0)
     writeUint16LE(central, 0)
     writeUint16LE(central, dosTime)
     writeUint16LE(central, dosDate)
     writeUint32LE(central, crc)
     writeUint32LE(central, dataBytes.length)
     writeUint32LE(central, dataBytes.length)
     writeUint16LE(central, nameBytes.length)
     writeUint16LE(central, 0)
     writeUint16LE(central, 0)
     writeUint16LE(central, 0)
     writeUint16LE(central, 0)
     writeUint32LE(central, 0)
     writeUint32LE(central, offset)
     centralChunks.push(new Uint8Array([...central, ...nameBytes]))

     offset += localHeader.length + dataBytes.length
   })

   const centralStart = offset
   const centralData = concatUint8Arrays(centralChunks)
   const end = []
   writeUint32LE(end, 0x06054b50)
   writeUint16LE(end, 0)
   writeUint16LE(end, 0)
   writeUint16LE(end, files.length)
   writeUint16LE(end, files.length)
   writeUint32LE(end, centralData.length)
   writeUint32LE(end, centralStart)
   writeUint16LE(end, 0)

   const zipData = concatUint8Arrays([...localChunks, centralData, new Uint8Array(end)])
   return new Blob([zipData], { type:mimeType })
 }

 function buildDeliveryInvoicesDocxBlob(invoices) {
   const documentXml = buildDeliveryInvoicesDocxDocument(invoices)
   const contentTypes = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/><Override PartName="/word/settings.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.settings+xml"/></Types>`
   const rootRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`
   const docRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings" Target="settings.xml"/></Relationships>`
   const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:b/><w:bCs/><w:sz w:val="16"/><w:szCs w:val="16"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr></w:pPrDefault></w:docDefaults></w:styles>`
   const settings = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:settings xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:zoom w:percent="100"/><w:compat><w:compatSetting w:name="compatibilityMode" w:uri="http://schemas.microsoft.com/office/word" w:val="15"/></w:compat></w:settings>`

   return createStoredZipBlob([
     { name:'[Content_Types].xml', data:contentTypes },
     { name:'_rels/.rels', data:rootRels },
     { name:'word/document.xml', data:documentXml },
     { name:'word/_rels/document.xml.rels', data:docRels },
     { name:'word/styles.xml', data:styles },
     { name:'word/settings.xml', data:settings }
   ], 'application/vnd.openxmlformats-officedocument.wordprocessingml.document')
 }

 function downloadDeliveryInvoiceDocxFile(filename, invoices) {
   const blob = buildDeliveryInvoicesDocxBlob(invoices)
   const url = URL.createObjectURL(blob)
   const link = document.createElement('a')
   link.href = url
   link.download = `${sanitizeWordFileName(filename)}.docx`
   document.body.appendChild(link)
   link.click()
   document.body.removeChild(link)
   setTimeout(() => URL.revokeObjectURL(url), 1500)
 }

