 async function saveReturn(invoice) {
 const items = returnItems[invoice.id]||[]
 const validItems = items.filter(i=>Number(i.returned_qty)>0)
 if (validItems.length===0) { showToast(' Enter at least one returned quantity.','red'); return }
 for (const item of validItems) {
 if (Number(item.returned_qty) > item.delivered_qty) { showToast(` ${item.variant_name}: returned qty cannot exceed delivered qty.`,'red'); return }
 }
 setSavingReturn(true)
 try {
 const totalCredit = validItems.reduce((s,i)=>s+Number(i.returned_qty)*i.reseller_price,0)
 const { data:ret, error:retErr } = await supabase.from('reseller_returns').insert({
 invoice_id:invoice.id, reseller_id:invoice.reseller_id, reseller_name:invoice.reseller_name,
 return_date:today, total_returned_amount:totalCredit, recorded_by:adminRole
 }).select().single()
 if (retErr) throw retErr
 await supabase.from('reseller_return_items').insert(validItems.map(i=>({
 return_id:ret.id, variant_id:i.variant_id, variant_name:i.variant_name,
 returned_quantity:Number(i.returned_qty), reseller_price:i.reseller_price,
 total_credit:Number(i.returned_qty)*i.reseller_price
 })))
 const newTotal = Math.max(0, Number(invoice.total_amount||0) - totalCredit)
 const totalReturned = validItems.reduce((s,i)=>s+Number(i.returned_qty),0)
 await supabase.from('delivery_invoices').update({ total_amount:newTotal, returns_amount:totalCredit, returns_qty:totalReturned, notes:(invoice.notes?invoice.notes+' | ':'')+'Returns: '+today }).eq('id', invoice.id)
 await logAudit('RETURNS RECORDED', adminRole, invoice.reseller_name, `${invoice.invoice_number} ${validItems.length} variants, ${totalReturned} pcs, credit: ${php(totalCredit)}`)
 // Cross-check with reseller portal
 await crossCheckReturns({...invoice, total_amount:newTotal})
 showToast(` Returns saved! ${totalReturned} pcs. Credit: ${php(totalCredit)} deducted.`)
 setShowReturnForm(p=>({...p,[invoice.id]:false}))
 loadDeliveryInvoices(); refreshFoundationAfterDataChange('returns-saved')
 } catch(err) { showToast(' Failed: '+err.message,'red') }
 setSavingReturn(false)
 }
 // Feature: CSV/XLSX Bulk Upload 
 async function handleInventoryCSV(e) {
 const file = e.target? e.target.files[0]: e
 if (!file) return
 setCsvUploading(true)
 try {
 let rows = []
 if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
 showToast(' Reading XLSX file...')
 await new Promise((resolve, reject) => {
 if (window['XLSX']) { resolve(); return }
 const script = document.createElement('script')
 script.src = 'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js'
 script.onload = resolve
 script.onerror = reject
 document.head.appendChild(script)
 })
 const XLSX = window['XLSX']
 if (!XLSX) throw new Error('XLSX library failed to load.')
 const buffer = await file.arrayBuffer()
 const wb = XLSX.read(buffer, { type:'array' })
 const ws = wb.Sheets[wb.SheetNames[0]]
 // Get raw data with header row
 const raw = XLSX.utils.sheet_to_json(ws, { header:1, defval:'' })
 if (raw.length < 3) { showToast(' File has no data rows.','red'); setCsvUploading(false); return }
 // Row 0 = headers, Row 1 = instructions (skip), Row 2+ = data
 const headerRow = raw[0].map(h=>String(h||'').replace(/\n/g,' ').trim().toLowerCase())
 // Find column indexes by flexible matching
 const findCol = (...keys) => { for(const k of keys){ const i=headerRow.findIndex(h=>h.includes(k)); if(i>=0) return i } return -1 }
 const nameIdx = findCol('item name','name')
 const catIdx = findCol('category')
 const unitIdx = findCol('unit')
 const stockIdx = findCol('current stock','stock on hand')
 const minIdx = findCol('min stock','reorder')
 const costIdx = findCol('cost per unit','cost per')
 const supplierIdx = findCol('supplier')
 // Parse from row 2 (index 2) onward, skip instruction row (index 1)
 rows = raw.slice(2).map(row=>{
 const name = String(row[nameIdx]||'').trim()
 if (!name || name.toLowerCase().includes('type item') || name.toLowerCase().includes('e.g.')) return null
 return {
 name,
 category: String(row[catIdx]||'Raw Ingredients').trim() || 'Raw Ingredients',
 unit: String(row[unitIdx]||'kg').trim() || 'kg',
 current_stock: Number(row[stockIdx]||0) || 0,
 min_stock: Number(row[minIdx]||0) || 0,
 cost_per_unit: Number(row[costIdx]||0) || 0,
 selling_price: 0,
 supplier_name: supplierIdx>=0? String(row[supplierIdx]||'').trim(): ''
 }
 }).filter(r=>r && r.name)
 } else {
 // Handle CSV
 const text = await file.text()
 const lines = text.split('\n').filter(l=>l.trim())
 if (lines.length < 2) { showToast(' CSV file is empty or has no data rows.','red'); setCsvUploading(false); return }
 const rawHeaders = lines[0].split(',').map(h=>h.trim().replace(/^"|"$/g,''))
 const headers = rawHeaders.map(h=>h.toLowerCase().replace(/[^a-z0-9]/g,'_').replace(/_+/g,'_').replace(/^_|_$/g,''))
 showToast(` Found ${lines.length-1} rows, ${headers.length} columns`)
 rows = lines.slice(1).map(line=>{
 const vals = line.split(',').map(v=>v.trim().replace(/^"|"$/g,''))
 const obj = {}
 rawHeaders.forEach((h,i)=>{ obj[h]=vals[i]||''; obj[h.toLowerCase()]=vals[i]||'' })
 headers.forEach((h,i)=>{ obj[h]=vals[i]||'' })
 // Map common variations
 return {
 name: obj.name || obj.item_name || obj.item || obj['item name'] || '',
 category: obj.category || 'Raw Ingredients',
 unit: obj.unit || obj.unit_of_measure || 'kg',
 current_stock: Number(obj.current_stock || obj.current_stock_on_hand || obj.stock || 0),
 min_stock: Number(obj.min_stock || obj.min_stock_level || obj.minimum || 0),
 cost_per_unit: Number(obj.cost_per_unit || obj.cost || obj.price || 0),
 selling_price: Number(obj.selling_price || 0),
 }
 }).filter(r=>r.name.trim())
 }
 if (rows.length === 0) { showToast(' No valid rows found. Check that your file has a "name" column.','red'); setCsvUploading(false); return }
 setCsvPreview(rows)
 setShowCsvPreview(true)
 } catch(err) { showToast(' Failed to read file: '+err.message,'red') }
 setCsvUploading(false)
 if (e.target) e.target.value = ''
 }
 async function confirmCSVUpload() {
 setCsvUploading(true)
 let success = 0, failed = 0
 for (const row of csvPreview) {
 try {
 await supabase.from('inventory_items').insert({
 name: row.name,
 category: row.category || 'Raw Ingredients',
 unit: row.unit || 'kg',
 current_stock: Number(row.current_stock||0),
 min_stock: Number(row.min_stock||0),
 cost_per_unit: Number(row.cost_per_unit||0),
 selling_price: Number(row.selling_price||0),
 is_active: true
 })
 success++
 } catch { failed++ }
 }
 showToast(` Uploaded ${success} items${failed>0?` (${failed} failed)`:''}!`)
 setShowCsvPreview(false); setCsvPreview([])
 loadInventoryItems()
 setCsvUploading(false)
 }

 // Feature: Reseller Portal 
 async function resellerLogin() {
 if (!resellerLoginCode ||!resellerLoginPin) { showToast(' Enter code and PIN.','red'); return }
 setLoading(true)
 try {
 const code = resellerLoginCode.trim().toUpperCase()
 const pinValue = resellerLoginPin.trim()

 // New professional login: main reseller account can own multiple branch/outlet records.
 let account = null
 try {
 const accountRes = await supabase
.from('reseller_accounts')
.select('*')
.ilike('access_code', code)
.eq('access_pin', pinValue)
.eq('is_active', true)
.maybeSingle()
 if (accountRes.error) console.warn('reseller account login fallback:', accountRes.error)
 account = accountRes.data || null
 } catch (err) {
 console.warn('reseller_accounts login not available yet:', err)
 }

 if (account?.id) {
 const { data:branches, error:branchErr } = await supabase
.from('resellers')
.select('*')
.eq('reseller_account_id', account.id)
.eq('is_active', true)
.order('name')
 if (branchErr) throw branchErr
 if (!branches || branches.length === 0) {
 showToast(' This reseller account has no linked branches yet. Link branches in Admin Sales & Resellers Resellers.', 'red')
 setLoading(false)
 return
 }
 setResellerPortalAccount(account)
 setResellerPortalBranches(branches)
 setCurrentReseller(branches[0])
 setSelectedResellerBranchId(branches[0].id)
 setResellerMode(true)
 setResellerPortalView('dashboard')
 await loadResellerPortalData(branches[0].id)
 setResellerOrderDeliveryDate(getDefaultResellerOrderDeliveryDate())
 await loadResellerOrderItems(branches[0].id)
 showToast(` Welcome, ${account.account_name || account.owner_name || 'Reseller'}!`)
 setLoading(false)
 return
 }

 // Backward-compatible legacy login for existing single-branch accounts.
 const { data, error } = await supabase
.from('resellers')
.select('*')
.ilike('access_code', code)
.eq('access_pin', pinValue)
.eq('is_active', true)
.maybeSingle()

 if (error) throw error
 if (!data) { showToast(' Invalid code/PIN or inactive reseller account.','red'); setLoading(false); return }

 setResellerPortalAccount(null)
 setResellerPortalBranches([data])
 setSelectedResellerBranchId(data.id)
 setCurrentReseller(data)
 setResellerMode(true)
 setResellerPortalView('dashboard')
 await loadResellerPortalData(data.id)

 setResellerOrderDeliveryDate(getDefaultResellerOrderDeliveryDate())
 await loadResellerOrderItems(data.id)
 showToast(` Welcome, ${data.name}!`)
 } catch(err) {
 showToast(' Reseller login failed: ' + (err?.message || err), 'red')
 }
 setLoading(false)
 }

 async function getAllOrderVariantRows(defaultRows = [], discountPct = 20) {
 let variants = Array.isArray(donutVariants)? donutVariants: []

 if (!variants || variants.length === 0) {
 const { data, error } = await supabase
.from('donut_variants')
.select('*')
.eq('is_active', true)
.order('category')
.order('name')

 if (!error && data && data.length > 0) {
 variants = data
 setDonutVariants(sortDonutVariantsByGuide(data))
 }
 }

 if (!variants || variants.length === 0) {
 variants = DONUT_VARIANTS_DEFAULT.map((v, idx) => ({
 id:`default-${idx}`,
 name:v.name,
 category:v.category,
 selling_price:v.selling_price
 }))
 }

 const defaultMap = new Map((defaultRows || []).map(row => [String(row.variant_id), row]))
 const rows = variants.map(v => {
 const saved = defaultMap.get(String(v.id))
 const retail = safeNum(v.selling_price, safeNum(saved?.retail_price, 0))
 const price = moneyRound(retail * (1 - safeNum(discountPct, 20) / 100))
 return {
 variant_id:v.id,
 variant_name:v.name || saved?.variant_name || 'Product',
 quantity:saved?.default_quantity? String(saved.default_quantity): '',
 retail_price:retail,
 reseller_price:price
 }
 })

 // Safety: if old saved template rows reference variants that are no longer in the active variant list,
 // still show them so old templates are not silently lost.
;(defaultRows || []).forEach(saved => {
 if (!rows.some(row => String(row.variant_id) === String(saved.variant_id))) {
 const retail = safeNum(saved.retail_price, 0)
 const price = moneyRound(retail * (1 - safeNum(discountPct, 20) / 100))
 rows.push({
 variant_id:saved.variant_id,
 variant_name:saved.variant_name || 'Archived Product',
 quantity:saved?.default_quantity? String(saved.default_quantity): '',
 retail_price:retail,
 reseller_price:price
 })
 }
 })

 return rows
 }

 async function loadResellerOrderItems(resellerId = null) {
 const templateSourceId = resellerId || currentReseller?.id || null
 let defaultRows = []

 if (templateSourceId) {
 const { data, error } = await supabase
.from('reseller_default_orders')
.select('*')
.eq('reseller_id', templateSourceId)

 if (error) console.warn('Unable to load reseller default order template:', error)
 defaultRows = data || []
 }

 const allRows = await getAllOrderVariantRows(defaultRows)
 setResellerOrderItems(allRows)
 }

 async function applyTemplateFromReseller(sourceResellerId, target = 'invoice', options = {}) {
 if (!sourceResellerId) {
 if (!options.silent) showToast(' Select a branch template first.', 'red')
 return false
 }
 const { data, error } = await supabase.from('reseller_default_orders').select('*').eq('reseller_id', sourceResellerId)
 if (error) {
 if (!options.silent) showToast(' Failed to load branch template: ' + error.message, 'red')
 return false
 }

 const items = await getAllOrderVariantRows(data || [], target === 'invoice' ? invoiceDiscountPct : 20)
 if (target === 'portal') setResellerOrderItems(items)
 else setInvoiceItems(items)

 if (!options.silent) {
 const branch = resellers.find(r => String(r.id) === String(sourceResellerId)) || resellerPortalBranches.find(r => String(r.id) === String(sourceResellerId))
 const savedCount = (data || []).filter(i => safeNum(i.default_quantity, 0) > 0).length
 const message = savedCount > 0
? ` Loaded all variants and copied ${savedCount} saved quantity/quantities from ${branch?.name || 'branch'} template.`
: ` Loaded all variants. No saved quantities yet for ${branch?.name || 'this branch'}, so quantities are blank.`
 showToast(message)
 }
 return true
 }

 async function switchResellerPortalBranch(branchId, keepCurrentView = false) {
 const branch = resellerPortalBranches.find(b => String(b.id) === String(branchId))
 if (!branch) return
 setCurrentReseller(branch)
 setSelectedResellerBranchId(branch.id)
 setResellerOrderTemplateSourceId('')
 if (!keepCurrentView) setResellerPortalView('dashboard')
 await loadResellerPortalData(branch.id)
 await loadResellerOrderItems(branch.id)
 showToast(` Switched to ${branch.name}`)
 }

 async function loadResellerPortalData(resellerId) {
 if (!resellerId) return
 setResellerPortalLoading(true)
 try {
 const branchIds = getResellerBranchIds(resellerId).filter(Boolean)
 const activeBranchIds = branchIds.length > 0? branchIds: [resellerId]

 const { data:invs, error:invErr } = await supabase
.from('delivery_invoices')
.select('*, delivery_invoice_items(*)')
.eq('reseller_id', resellerId)
.order('delivery_date',{ascending:false})
.limit(80)
 if (!invErr) setResellerInvoices(invs||[])
 else {
 console.warn('Reseller invoices load error:', invErr)
 setResellerInvoices([])
 }

 const { data:pays, error:payErr } = await supabase
.from('reseller_payments')
.select('*')
.in('reseller_id', activeBranchIds)
.order('payment_date',{ascending:false})
.limit(120)
 if (!payErr) setResellerPaymentHistory(pays||[])
 else {
 console.warn('Reseller payments load error:', payErr)
 setResellerPaymentHistory([])
 }

 const { data:orders, error:ordErr } = await supabase
.from('reseller_orders')
.select('*, reseller_order_items(*)')
.in('reseller_id', activeBranchIds)
.order('created_at',{ascending:false})
.limit(80)
 if (!ordErr) setResellerOrders(orders||[])
 else {
 console.warn('Reseller orders load error:', ordErr)
 setResellerOrders([])
 }

 const { data:returns, error:returnErr } = await supabase
.from('reseller_returns')
.select('*, reseller_return_items(*)')
.in('reseller_id', activeBranchIds)
.order('return_date',{ascending:false})
.limit(100)
 if (!returnErr) setResellerReturns(returns||[])
 else {
 console.warn('Reseller returns load error:', returnErr)
 setResellerReturns([])
 }

 const noticeFilter = activeBranchIds.length > 0
? `reseller_id.in.(${activeBranchIds.join(',')}),reseller_id.is.null`
: `reseller_id.eq.${resellerId},reseller_id.is.null`
 const { data:notices, error:noticeErr } = await supabase
.from('reseller_notices')
.select('*')
.or(noticeFilter)
.order('created_at',{ascending:false})
.limit(30)
 if (!noticeErr) setResellerNotices((notices||[]).filter(n=>String(n.status||'active').toLowerCase()!== 'archived'))
 else {
 console.warn('Reseller notices load error:', noticeErr)
 setResellerNotices([])
 }
 } catch (err) {
 console.warn('loadResellerPortalData failed:', err)
 setResellerInvoices([])
 setResellerPaymentHistory([])
 setResellerOrders([])
 setResellerReturns([])
 setResellerNotices([])
 showToast(' Reseller portal data could not fully load. Please refresh or check Supabase setup.', 'red')
 } finally {
 setResellerPortalLoading(false)
 }
 }

