 // Department Location Management 
 async function saveDepartmentLocations(locs) {
 try {
 let updatedEmployees = 0
 for (const [dept, loc] of Object.entries(locs)) {
 if (!loc) continue
 // Save to department_locations table
 await supabase.from('department_locations').upsert({
 department: dept,
 location_name: loc.name || null,
 latitude: loc.lat? Number(loc.lat): null,
 longitude: loc.lng? Number(loc.lng): null,
 radius_meters: Number(loc.radius || 200),
 is_active: true,
 updated_at: new Date().toISOString()
 }, { onConflict: 'department' })
 // Auto-apply to all employees in this department
 if (loc.lat && loc.lng) {
 const { data: deptEmps } = await supabase.from('employees')
.select('id')
.eq('department', dept)
.eq('is_active', true)
 if (deptEmps && deptEmps.length > 0) {
 await supabase.from('employees').update({
 work_location: loc.name || dept,
 location_lat: String(loc.lat),
 location_lng: String(loc.lng),
 location_radius: String(loc.radius || 200)
 }).eq('department', dept).eq('is_active', true)
 updatedEmployees += deptEmps.length
 }
 }
 }
 setDepartmentLocations(locs)
 await loadEmployees()
 showToast(` Locations saved! Auto-applied to ${updatedEmployees} employee(s).`)
 } catch(err) {
 showToast(' Failed: ' + err.message, 'red')
 }
 }
 async function loadDepartmentLocations() {
 try {
 // Try Supabase first
 const { data, error } = await supabase.from('department_locations').select('*').eq('is_active', true)
 if (!error && data && data.length > 0) {
 const locs = {}
 data.forEach(row => {
 locs[row.department] = {
 name: row.location_name || '',
 lat: row.latitude || '',
 lng: row.longitude || '',
 radius: row.radius_meters || 200
 }
 })
 setDepartmentLocations(locs)
 return
 }
 // Fallback to localStorage
 const saved = localStorage.getItem('dept_locations')
 if (saved) setDepartmentLocations(JSON.parse(saved))
 } catch(e) {
 try {
 const saved = localStorage.getItem('dept_locations')
 if (saved) setDepartmentLocations(JSON.parse(saved))
 } catch(e2) {}
 }
 }

 // Payroll Approval Workflow 
 function isOutstandingCashAdvance(ca) {
 const balance = Math.max(0, safeNum(ca?.balance, 0))
 const status = String(ca?.status || '').trim().toLowerCase()
 if (status === 'cancelled' || status === 'void') return false
 return balance > 0.009
 }

 function getCashAdvancePayrollDeduction(ca) {
 if (!isOutstandingCashAdvance(ca)) return 0
 const balance = Math.max(0, safeNum(ca?.balance, 0))
 const scheduled = safeNum(ca?.per_payroll_deduction, 0) > 0? safeNum(ca?.per_payroll_deduction, 0): balance
 return Math.min(balance, scheduled)
 }

 function buildCADeductionTag(start, end) {
 return `CA_PAYROLL:${start}|${end}`
 }

 async function caPayrollDeductionsAlreadyApplied(start, end) {
 const tag = buildCADeductionTag(start, end)
 const { data:appliedRows, error:appliedError } = await supabase
.from('audit_logs')
.select('id, details, created_at')
.eq('action', 'CA PAYROLL DEDUCTIONS APPLIED')
.ilike('details', `%${tag}%`)
.order('created_at', { ascending:false })
.limit(5)

 if (appliedError) return { exists:false, error:appliedError.message }
 const applied = appliedRows || []
 if (applied.length === 0) return { exists:false, record:null }

 const { data:reversedRows, error:reversedError } = await supabase
.from('audit_logs')
.select('id, details, created_at')
.eq('action', 'CA PAYROLL DEDUCTIONS REVERSED')
.ilike('details', `%${tag}%`)
.order('created_at', { ascending:false })
.limit(1)

 if (reversedError) console.warn('CA reversal audit check skipped:', reversedError.message)

 const latestApplied = applied[0]
 const latestReverse = (reversedRows || [])[0] || null
 const appliedTime = latestApplied?.created_at? new Date(latestApplied.created_at).getTime(): 0
 const reverseTime = latestReverse?.created_at? new Date(latestReverse.created_at).getTime(): 0
 if (latestReverse && reverseTime >= appliedTime) {
  return { exists:false, reversed:true, record:latestApplied, reverseRecord:latestReverse }
 }

 return { exists:true, record:latestApplied }
 }

 async function applyCashAdvanceDeductionsForPayrollPeriod(start, end, options = {}) {
 if (!start ||!end) return { applied:false, amount:0, error:'Missing payroll period.' }

 const existing = await caPayrollDeductionsAlreadyApplied(start, end)
 if (existing.exists) return { applied:false, existing:true, amount:0 }

 const { data:records, error:payrollError } = await supabase
.from('payroll_records')
.select('id, employee_id, employee_code, employee_name, cash_advance_deduction')
.eq('payroll_start', start)
.eq('payroll_end', end)

 if (payrollError) return { applied:false, amount:0, error:payrollError.message }

 const rows = (records || []).filter(r => safeNum(r.cash_advance_deduction, 0) > 0)
 if (rows.length === 0) return { applied:false, amount:0, none:true }

 let totalApplied = 0
 const warnings = []

 for (const row of rows) {
 let remaining = safeNum(row.cash_advance_deduction, 0)
 if (remaining <= 0) continue

 const { data:cas, error:caError } = await supabase
.from('cash_advances')
.select('*')
.eq('employee_id', row.employee_id)
.order('advance_date', { ascending:true })

 if (caError) return { applied:false, amount:totalApplied, error:caError.message }

 const openCAs = (cas || []).filter(isOutstandingCashAdvance)
 for (const ca of openCAs) {
 if (remaining <= 0) break
 const balance = Math.max(0, safeNum(ca.balance, 0))
 if (balance <= 0) continue

 const deduction = Math.min(balance, remaining)
 const newPaid = moneyRound(safeNum(ca.amount_paid, 0) + deduction)
 const newBal = moneyRound(Math.max(0, balance - deduction))
 const newRem = Math.max(0, safeNum(ca.installments_remaining, 1) - 1)

 const { error:updateError } = await supabase.from('cash_advances').update({
 amount_paid:newPaid,
 balance:newBal,
 installments_remaining:newRem,
 status:isMoneySettled(newBal)? 'Paid': 'Unpaid'
 }).eq('id', ca.id)

 if (updateError) return { applied:false, amount:totalApplied, error:updateError.message }

 totalApplied += deduction
 remaining = Math.max(0, remaining - deduction)
 }

 if (remaining > 0.009) warnings.push(`${row.employee_name || row.employee_code}: ${php(remaining)} payroll CA deduction had no matching unpaid CA balance`)
 }

 await logAudit(
 'CA PAYROLL DEDUCTIONS APPLIED',
 options.auto? 'System Auto': 'Admin',
 'ALL',
 `${buildCADeductionTag(start, end)} | Applied: ${php(totalApplied)} | Employees: ${rows.length}${warnings.length? ' | Warnings: ' + warnings.join('; '): ''}`
 )

 return { applied:true, amount:totalApplied, warnings }
 }

 async function reverseCashAdvanceDeductionsForPayrollPeriod(start, end, options = {}) {
 if (!start ||!end) return { reversed:false, amount:0, error:'Missing payroll period.' }
 const tag = buildCADeductionTag(start, end)

 const { data:records, error:payrollError } = await supabase
.from('payroll_records')
.select('id, employee_id, employee_code, employee_name, cash_advance_deduction')
.eq('payroll_start', start)
.eq('payroll_end', end)
.limit(1000)

 if (payrollError) return { reversed:false, amount:0, error:payrollError.message }

 const rows = (records || []).filter(r => safeNum(r.cash_advance_deduction, 0) > 0)
 if (rows.length === 0) return { reversed:false, amount:0, none:true }

 const byEmployee = {}
 rows.forEach(row => {
  const key = String(row.employee_id || '')
  if (!key) return
  if (!byEmployee[key]) byEmployee[key] = { employee_id:row.employee_id, employee_code:row.employee_code || '', employee_name:row.employee_name || '', amount:0 }
  byEmployee[key].amount += safeNum(row.cash_advance_deduction, 0)
 })

 let totalReversed = 0
 const warnings = []

 for (const employeeRow of Object.values(byEmployee)) {
  let remaining = moneyRound(employeeRow.amount)
  if (remaining <= 0) continue

  const { data:cas, error:caError } = await supabase
  .from('cash_advances')
  .select('*')
  .eq('employee_id', employeeRow.employee_id)
  .lte('advance_date', end)

  if (caError) return { reversed:false, amount:totalReversed, error:caError.message }

  const caRows = (cas || [])
  .filter(ca => {
   const status = String(ca.status || '').trim().toLowerCase()
   return status !== 'cancelled' && status !== 'void' && safeNum(ca.amount_paid, 0) > 0
  })
  .sort((a,b) => String(b.advance_date || b.created_at || '').localeCompare(String(a.advance_date || a.created_at || '')))

  for (const ca of caRows) {
   if (remaining <= 0.009) break
   const paidNow = Math.max(0, safeNum(ca.amount_paid, 0))
   if (paidNow <= 0) continue

   const reversal = moneyRound(Math.min(paidNow, remaining))
   const totalAmount = safeNum(ca.amount, paidNow + safeNum(ca.balance, 0))
   const newPaid = moneyRound(Math.max(0, paidNow - reversal))
   const newBalance = moneyRound(Math.max(0, totalAmount - newPaid))
   const totalInstallments = safeNum(ca.installments_total, 0)
   const currentRemainingInstallments = safeNum(ca.installments_remaining, 0)
   const restoredInstallments = totalInstallments > 0
    ? Math.min(totalInstallments, currentRemainingInstallments + 1)
    : currentRemainingInstallments + 1

   const { error:updateError } = await supabase.from('cash_advances').update({
    amount_paid:newPaid,
    balance:newBalance,
    installments_remaining:restoredInstallments,
    status:isMoneySettled(newBalance)? 'Paid': 'Unpaid'
   }).eq('id', ca.id)

   if (updateError) return { reversed:false, amount:totalReversed, error:updateError.message }

   totalReversed = moneyRound(totalReversed + reversal)
   remaining = moneyRound(Math.max(0, remaining - reversal))
  }

  if (remaining > 0.009) warnings.push(`${employeeRow.employee_name || employeeRow.employee_code}: ${php(remaining)} CA reversal could not be matched to paid CA records`)
 }

 await logAudit(
  'CA PAYROLL DEDUCTIONS REVERSED',
  options.auto? 'System Auto': currentAdminLabel,
  'ALL',
  `${tag} | Reversed: ${php(totalReversed)} | Employees: ${Object.keys(byEmployee).length}${warnings.length? ' | Warnings: ' + warnings.join('; '): ''}`
 )

 return { reversed:true, amount:totalReversed, warnings }
 }

 async function reopenReleasedPayroll(start = payrollStart, end = payrollEnd) {
 if (!requireOwnerOrPayrollAction('reopen released payroll')) return
 if (!start ||!end) { showToast('Please select payroll start and end dates.', 'red'); return }

 const { data:records, error:recordsError } = await supabase
 .from('payroll_records')
 .select('id, employee_id, employee_code, employee_name, employee_acknowledgement, payroll_approved, approved_at, cash_advance_deduction')
 .eq('payroll_start', start)
 .eq('payroll_end', end)
 .limit(1000)

 if (recordsError) { showToast('Failed to check payroll: '+recordsError.message, 'red'); return }
 if (!records || records.length === 0) { showToast('No payroll records found for this period.', 'red'); return }

 const releasedRows = records.filter(isReleasedPayrollRecord)
 if (releasedRows.length === 0) { showToast('This payroll is not released. Use Undo Draft Payroll instead.', 'red'); return }

 const expenseExisting = await payrollExpenseAlreadyPosted(start, end)
 if (expenseExisting.error) { showToast('Failed to verify payroll expense posting: '+expenseExisting.error, 'red'); return }
 if (expenseExisting.exists) {
  showToast('Reopen blocked: payroll was already posted to Expenses. Reverse the expense first before reopening payroll.', 'red')
  await logAudit('REOPEN RELEASED PAYROLL BLOCKED - EXPENSE POSTED', currentAdminLabel, 'Payroll', `Period: ${start} to ${end} | Expense ID: ${expenseExisting.record?.id || ''}`)
  return
 }

 const caTotal = records.reduce((sum,row)=>sum+safeNum(row.cash_advance_deduction,0),0)
 const warning = [
  `REOPEN released payroll for ${start} to ${end}?`,
  `Released rows: ${releasedRows.length}`,
  `Cash advance deductions to reverse: ${php(caTotal)}`,
  'This will return payslips to DRAFT/admin-only, reverse payroll CA deductions, and allow you to undo/recompute the cutoff.',
  'Only continue if employees were NOT paid yet and payroll was NOT posted to expenses.'
 ].join('\n')
 if (!window.confirm(warning)) return

 let caReverseResult = { reversed:false, amount:0, none:true }
 if (caTotal > 0.009) {
  caReverseResult = await reverseCashAdvanceDeductionsForPayrollPeriod(start, end, { auto:false })
  if (caReverseResult.error) {
   showToast('Reopen stopped: CA reversal failed: '+caReverseResult.error, 'red')
   await logAudit('REOPEN RELEASED PAYROLL FAILED - CA REVERSAL', currentAdminLabel, 'Payroll', `Period: ${start} to ${end} | Error: ${caReverseResult.error}`)
   return
  }
 }

 const primaryUpdate = {
  payroll_approved:false,
  approved_by:null,
  approved_at:null,
  payroll_status:'draft',
  employee_acknowledgement:'draft',
  review_sent_at:null,
  review_sent_by:null
 }
 let updateError = null
 const { error:firstUpdateError } = await supabase.from('payroll_records')
 .update(primaryUpdate)
 .eq('payroll_start', start)
 .eq('payroll_end', end)

 if (firstUpdateError && isMissingPayrollWorkflowColumnError(firstUpdateError)) {
  const { error:fallbackError } = await supabase.from('payroll_records')
  .update({ payroll_approved:false, approved_by:null, approved_at:null, employee_acknowledgement:'draft' })
  .eq('payroll_start', start)
  .eq('payroll_end', end)
  updateError = fallbackError
 } else {
  updateError = firstUpdateError
 }

 if (updateError) {
  showToast('Reopen failed after CA reversal. Payroll status update failed: '+updateError.message, 'red')
  await logAudit('REOPEN RELEASED PAYROLL FAILED - STATUS UPDATE', currentAdminLabel, 'Payroll', `Period: ${start} to ${end} | Error: ${updateError.message}`)
  return
 }

 try {
  await supabase.from('payroll_periods')
  .update({ review_sent_at:null, review_sent_by:null, acknowledge_deadline:null })
  .eq('payroll_start', start)
  .eq('payroll_end', end)
 } catch(e) { console.warn('Payroll period reopen cleanup skipped:', e) }

 try {
  await supabase.from('payslip_disputes')
  .update({ status:'voided', admin_reason:`Released payroll reopened for recomputation by ${currentAdminLabel}`, reviewed_by:currentAdminLabel, reviewed_at:new Date().toISOString() })
  .eq('payroll_start', start)
  .eq('payroll_end', end)
  .neq('status','resolved')
 } catch(e) { console.warn('Dispute voiding skipped:', e) }

 setPayrollApproved(false)
 await logAudit('RELEASED PAYROLL REOPENED', currentAdminLabel, 'Payroll', `Period: ${start} to ${end} | Rows: ${records.length} | CA reversed: ${caReverseResult.reversed? php(caReverseResult.amount): 'none'}`)
 await loadSavedPayrollForPeriod(start, end, { silent:true })
 loadPayrollHistory()
 if (cashAdvanceCoveragePeriod === `${start}|${end}`) await loadCashAdvanceCoverage(start, end)
 showToast(`Released payroll reopened. CA reversed: ${caReverseResult.reversed? php(caReverseResult.amount): 'none'}. Now click Undo Draft Payroll, then Compute Draft Payroll.`, 'green')
 }

 async function approvePayroll(start, end) {
 if (!requireOwnerOrPayrollAction('release payroll')) return
 if (!start ||!end) { showToast('Please select payroll start and end dates.', 'red'); return }

 const { data: records, error:recordsError } = await supabase
 .from('payroll_records')
 .select('id,employee_name,employee_code,employee_acknowledgement,payroll_approved,approved_at,cash_advance_deduction,total_earnings,total_deductions,non_ca_deduction_overflow')
 .eq('payroll_start', start)
 .eq('payroll_end', end)
 .limit(1000)

 if (recordsError) { showToast('Failed: '+recordsError.message, 'red'); return }

 if (!records || records.length === 0) {
  showToast('No payroll records found for this period. Compute payroll first.', 'red')
  return
 }

 const draftCount = records.filter(isDraftPayrollRecord).length
 if (draftCount > 0) {
  showToast(`Release blocked: ${draftCount} payslip(s) are still draft/admin-only. Click SEND PAYSLIPS TO EMPLOYEES FOR REVIEW first.`, 'red')
  await logAudit('PAYROLL RELEASE BLOCKED - NOT SENT FOR REVIEW', currentAdminLabel, 'Payroll', `Period: ${start} to ${end} | Draft rows: ${draftCount}`)
  return
 }

 const disputedCount = records.filter(r => normalizePayrollAcknowledgement(r.employee_acknowledgement) === 'disputed').length
 if (disputedCount > 0) {
  showToast(`Release blocked: ${disputedCount} payslip dispute(s) must be resolved before final payroll release.`, 'red')
  await logAudit('PAYROLL RELEASE BLOCKED - DISPUTES', currentAdminLabel, 'Payroll', `Period: ${start} to ${end} | Disputed rows: ${disputedCount}`)
  return
 }

 const overDeductedRows = records.filter(r => safeNum(r.non_ca_deduction_overflow, 0) > 0.009 || safeNum(r.total_deductions,0) - safeNum(r.total_earnings,0) > 0.009)
 if (overDeductedRows.length > 0) {
  const names = overDeductedRows.slice(0, 5).map(r => r.employee_name || r.employee_code || 'Employee').join(', ')
  showToast(`Release blocked: ${overDeductedRows.length} payslip(s) have deductions higher than earnings. Review/correct first: ${names}${overDeductedRows.length>5?'...':''}`, 'red')
  await logAudit('PAYROLL RELEASE BLOCKED - OVER DEDUCTION', currentAdminLabel, 'Payroll', `Period: ${start} to ${end} | Rows: ${overDeductedRows.length} | ${names}`)
  return
 }

 const pendingCount = records.filter(r => {
  const ack = normalizePayrollAcknowledgement(r.employee_acknowledgement)
  return !ack || ack === 'pending'
 }).length
 if (pendingCount > 0 && !window.confirm(`${pendingCount} payslip(s) are still pending employee acknowledgement. Continue final payroll release?`)) return

 const alreadyReleased = records.some(r => r.payroll_approved === true ||!!r.approved_at)
 if (alreadyReleased) {
  const hasCADeductions = records.some(r => safeNum(r.cash_advance_deduction, 0) > 0)
  const caExisting = hasCADeductions? await caPayrollDeductionsAlreadyApplied(start, end): { exists:true, none:true }
  const expenseExisting = await payrollExpenseAlreadyPosted(start, end)

  if ((!hasCADeductions || caExisting.exists) && expenseExisting.exists) {
   showToast(' This payroll period is already fully released. Releasing it again is blocked to prevent duplicate CA deductions or expense posting.', 'red')
   await logAudit('DUPLICATE PAYROLL RELEASE BLOCKED', currentAdminLabel, 'Payroll', `Period: ${start} to ${end}`)
   return
  }

  showToast(' Payroll was already marked released, but one release step is missing. The system will safely recover only the missing CA/expense step.', 'red')
  await logAudit('PAYROLL RELEASE RECOVERY STARTED', currentAdminLabel, 'Payroll', `Period: ${start} to ${end} | CA done: ${!hasCADeductions || caExisting.exists} | Expense done: ${expenseExisting.exists}`)
 } else {
  let updatePayload = { payroll_approved: true, approved_by: currentAdminLabel, approved_at: new Date().toISOString(), payroll_status:'released' }
  const { error:firstUpdateError } = await supabase.from('payroll_records')
  .update(updatePayload)
  .eq('payroll_start', start).eq('payroll_end', end)
  if (firstUpdateError && isMissingPayrollWorkflowColumnError(firstUpdateError)) {
   const { error:fallbackUpdateError } = await supabase.from('payroll_records')
   .update({ payroll_approved: true, approved_by: currentAdminLabel, approved_at: new Date().toISOString() })
   .eq('payroll_start', start).eq('payroll_end', end)
   if (fallbackUpdateError) { showToast('Failed: '+fallbackUpdateError.message,'red'); return }
  } else if (firstUpdateError) { showToast('Failed: '+firstUpdateError.message,'red'); return }
 }

 const releasedSILCount = await markSILCashoutsReleasedForPayrollPeriod(start, end, { auto:true, silent:true })
 const caDeductionResult = await applyCashAdvanceDeductionsForPayrollPeriod(start, end, { auto:true, silent:true })
 if (caDeductionResult.error) {
  setPayrollApproved(true)
  await logAudit('PAYROLL RELEASE CA DEDUCTION FAILED', currentAdminLabel, 'Payroll', `Period: ${start} to ${end} | Error: ${caDeductionResult.error}`)
  showToast('Payroll was marked released, but CA deduction update failed: ' + caDeductionResult.error + '. Fix the database issue, then click RELEASE PAYROLL again to recover the missing step safely.', 'red')
  return
 }

 const expenseResult = await postPayrollToExpenses(start, end, { auto:true, silent:true })

 setPayrollApproved(true)
 await logAudit(
  'PAYROLL APPROVED',
  currentAdminLabel,
  'ALL',
  `Period: ${start} to ${end} | SIL cashouts auto-released: ${releasedSILCount} | CA deductions: ${caDeductionResult.applied? 'applied ' + php(caDeductionResult.amount): caDeductionResult.existing? 'already applied': caDeductionResult.none? 'none': 'not applied'} | Expense: ${expenseResult.posted? 'posted ' + php(expenseResult.amount): expenseResult.existing? 'already posted': 'not posted'}`
 )

 const messages = [' Payroll approved and released!']
 if (releasedSILCount > 0) messages.push(`${releasedSILCount} SIL cashout(s) marked paid.`)
 if (caDeductionResult.applied) messages.push(`CA deductions applied: ${php(caDeductionResult.amount)}.`)
 else if (caDeductionResult.existing) messages.push('CA deductions were already applied for this payroll period.')
 else if (caDeductionResult.error) messages.push(`CA deductions not applied: ${caDeductionResult.error}`)
 if (expenseResult.posted) messages.push(`Payroll expense posted: ${php(expenseResult.amount)}.`)
 else if (expenseResult.existing) messages.push('Payroll expense was already posted.')
 else if (expenseResult.error) messages.push(`Payroll expense not posted: ${expenseResult.error}`)

 showToast(messages.join(' '), (expenseResult.error || caDeductionResult.error)? 'red': 'green')
 loadSILCashouts({ skipAuto:true })
 loadDailyExpenses()
 refreshFoundationAfterDataChange('payroll-approved')
 }

 function buildPayrollExpenseTag(start, end) {
 return `PAYROLL:${start}|${end}`
 }

 function getPayrollExpenseDescription(start, end, summary) {
 const tag = buildPayrollExpenseTag(start, end)
 return `${tag} | Payroll expense for ${start} to ${end} | Employees: ${summary.employeeCount} | Operating payroll posted as expense: ${php(summary.operatingPayrollExpense ?? summary.grossEarnings)} | Direct production labor moved to COGS: ${php(summary.productionLaborCOGS || 0)} | Total gross earnings: ${php(summary.grossEarnings)} | Net pay released: ${php(summary.netPay)} | Cash advance deductions: ${php(summary.cashAdvanceDeduction || 0)} (loan repayment only NOT added as payroll expense). | Includes basic salary, overtime, night differential, holiday pay, paid SIL, unused SIL conversion, and payroll additions.`
 }

 async function payrollExpenseAlreadyPosted(start, end) {
 const tag = buildPayrollExpenseTag(start, end)
 const { data, error } = await supabase
.from('daily_expenses')
.select('id, amount, status, expense_date, description')
.eq('category', 'Payroll Expense')
.ilike('description', `%${tag}%`)
.limit(1)

 if (error) return { exists:false, error:error.message }
 return { exists:(data || []).length > 0, record:(data || [])[0] || null }
 }

 async function payrollPeriodHasReleasedRecords(start, end) {
 const { data, error } = await supabase
.from('payroll_records')
.select('id,payroll_approved,approved_at')
.eq('payroll_start', start)
.eq('payroll_end', end)
.limit(500)

 if (error) return { released:false, count:0, error:error.message }
 const records = data || []
 return {
 released: records.length > 0 && records.some(r => r.payroll_approved === true ||!!r.approved_at),
 count: records.length
 }
 }

 async function getPayrollExpenseSummary(start, end) {
 const { data, error } = await supabase
.from('payroll_records')
.select('*')
.eq('payroll_start', start)
.eq('payroll_end', end)

 if (error) return { error:error.message }
 const records = data || []
 if (records.length === 0) return { error:'No payroll records found. Compute payroll first.' }

 const employeeIds = Array.from(new Set(records.map(r=>r.employee_id).filter(Boolean)))
 let payrollEmployees = []
 if (employeeIds.length > 0) {
 const empRes = await supabase.from('employees').select('id,employee_code,full_name,position,department,payroll_cost_type').in('id', employeeIds)
 if (!empRes.error) payrollEmployees = empRes.data || []
 }
 const classified = classifyPayrollRecords(records, payrollEmployees, { includeUnreleased:true })

 return {
 employeeCount: records.length,
 grossEarnings: records.reduce((s,r)=>s+safeNum(r.total_earnings,0),0),
 netPay: records.reduce((s,r)=>s+safeNum(r.net_pay,0),0),
 productionLaborCOGS: classified.productionLaborCOGS,
 operatingPayrollExpense: classified.operatingPayrollExpense,
 payrollByType: classified.byType,
 basicPay: records.reduce((s,r)=>s+safeNum(r.basic_pay,0),0),
 birthdayPay: records.reduce((s,r)=>s+safeNum(r.birthday_pay,0),0),
 overtimePay: records.reduce((s,r)=>s+safeNum(r.overtime_pay,0),0),
 nightDiffPay: records.reduce((s,r)=>s+safeNum(r.night_diff_pay,0),0),
 holidayPay: records.reduce((s,r)=>s+safeNum(r.holiday_pay,0),0),
 otherEarnings: records.reduce((s,r)=>s+safeNum(r.other_earnings,0),0),
 totalDeductions: records.reduce((s,r)=>s+safeNum(r.total_deductions,0),0),
 cashAdvanceDeduction: records.reduce((s,r)=>s+safeNum(r.cash_advance_deduction,0),0)
 }
 }

 async function postPayrollToExpenses(start, end, options = {}) {
 if (!start ||!end) return { posted:false, error:'Missing payroll period.' }

 const existing = await payrollExpenseAlreadyPosted(start, end)
 if (existing.exists) {
 if (!options.silent) showToast('Payroll expense is already posted for this period.', 'red')
 return { posted:false, existing:true, record:existing.record, amount:safeNum(existing.record?.amount,0) }
 }
 if (existing.error &&!options.silent) console.warn('Payroll expense duplicate check:', existing.error)

 const summary = await getPayrollExpenseSummary(start, end)
 if (summary.error) {
 if (!options.silent) showToast(summary.error, 'red')
 return { posted:false, error:summary.error }
 }

 const amount = safeNum(summary.operatingPayrollExpense, 0)
 if (amount <= 0) {
 const msg = 'Operating payroll expense is zero. Production payroll is still counted under COGS after payroll release.'
 if (!options.silent) showToast(msg, 'red')
 return { posted:false, error:msg }
 }

 const payload = {
 expense_date: end,
 category: 'Payroll Expense',
 amount,
 description: getPayrollExpenseDescription(start, end, summary),
 status: 'approved',
 encoded_by: options.auto? 'System Auto': (adminRole || 'Admin'),
 approved_by: options.auto? 'System Auto': (adminRole || 'Admin'),
 approved_at: new Date().toISOString()
 }

 const { data, error } = await supabase.from('daily_expenses').insert(payload).select().single()
 if (error) {
 if (!options.silent) showToast('Failed to post payroll expense: ' + error.message, 'red')
 return { posted:false, error:error.message }
 }

 await logAudit(
 options.auto? 'PAYROLL EXPENSE AUTO-POSTED': 'PAYROLL EXPENSE POSTED',
 options.auto? 'System Auto': 'Admin',
 'ALL',
 `Period: ${start} to ${end} | Operating payroll expense: ${php(amount)} | Production labor COGS: ${php(summary.productionLaborCOGS || 0)} | Net pay: ${php(summary.netPay)} | Expense ID: ${data?.id || ''}`
 )

 if (!options.silent) showToast(` Operating payroll expense posted: ${php(amount)}. Production labor COGS: ${php(summary.productionLaborCOGS || 0)}.`)
 loadDailyExpenses()
 if (financialMonth === String(end).slice(0,7)) loadFinancialData()
 refreshFoundationAfterDataChange('payroll-expense-posted')
 return { posted:true, amount, record:data, summary }
 }

 async function autoPostApprovedPayrollExpenses(options = {}) {
 try {
 const { data, error } = await supabase
.from('payroll_records')
.select('payroll_start,payroll_end,payroll_approved,cash_advance_deduction')
.eq('payroll_approved', true)
.order('payroll_start', { ascending:false })
.limit(300)

 if (error) return 0

 const periods = {}
;(data || []).forEach(r => {
 if (!r.payroll_start ||!r.payroll_end) return
 const key = `${r.payroll_start}|${r.payroll_end}`
 if (!periods[key]) periods[key] = { start:r.payroll_start, end:r.payroll_end, hasCADeductions:false }
 if (safeNum(r.cash_advance_deduction, 0) > 0) periods[key].hasCADeductions = true
 })

 let posted = 0
 for (const p of Object.values(periods)) {
 if (p.hasCADeductions) {
 const caResult = await applyCashAdvanceDeductionsForPayrollPeriod(p.start, p.end, { auto:true, silent:true })
 if (caResult.error) {
 await logAudit('PAYROLL EXPENSE AUTO-POST SKIPPED', 'System Auto', 'ALL', `Period: ${p.start} to ${p.end} | CA deduction failed first: ${caResult.error}`)
 continue
 }
 }
 const result = await postPayrollToExpenses(p.start, p.end, { auto:true, silent:true })
 if (result.posted) posted++
 }

 if (posted > 0) {
 await logAudit('PAYROLL EXPENSE AUTO-POST CHECK', 'System Auto', 'ALL', `${posted} approved payroll period(s) auto-posted to expenses`)
 if (!options.silent) showToast(` ${posted} payroll expense record(s) auto-posted.`)
 }
 return posted
 } catch(e) {
 console.warn('Auto payroll expense post skipped:', e)
 return 0
 }
 }

 async function handleManualPayrollExpensePost(start, end) {
 if (!start ||!end) { showToast('Please select a payroll period.', 'red'); return }

 const releasedCheck = await payrollPeriodHasReleasedRecords(start, end)
 if (releasedCheck.error) { showToast('Failed to verify payroll release status: ' + releasedCheck.error, 'red'); return }
 if (!releasedCheck.count) { showToast('No payroll records found. Compute payroll first.', 'red'); return }
 if (!releasedCheck.released) {
 showToast('Release payroll first. Payroll expense posting is blocked until payroll is approved/released so expenses will not be posted from a draft computation.', 'red')
 return
 }

 if (!window.confirm(`Post payroll to Expenses for ${start} to ${end}?

This recovery button creates one approved expense record using GROSS payroll earnings only. Cash advance deductions are loan repayments and will NOT be added as extra expense.`)) return
 const result = await postPayrollToExpenses(start, end, { auto:false })
 if (result.existing) showToast('Payroll expense is already posted for this period.', 'red')
 }



 // Foundation Control Center 
 function getMonthRange(monthValue) {
 const [year, month] = String(monthValue || today.slice(0,7)).split('-').map(Number)
 const start = `${year}-${String(month).padStart(2,'0')}-01`
 const end = new Date(year, month, 0).toISOString().slice(0,10)
 return { start, end, year, month }
 }

 function daysBetweenLocal(start, end = today) {
 const s = parseLocalDate(start)
 const e = parseLocalDate(end)
 if (!s ||!e) return 0
 return Math.max(0, Math.floor((e.getTime() - s.getTime()) / (1000 * 60 * 60 * 24)))
 }

 async function foundationSelect(table, select = '*', buildQuery) {
 try {
 let query = supabase.from(table).select(select)
 if (typeof buildQuery === 'function') query = buildQuery(query)
 const { data, error } = await query
 if (error) return { data:[], error:`${table}: ${error.message}` }
 return { data:data || [], error:null }
 } catch(e) {
 return { data:[], error:`${table}: ${e.message}` }
 }
 }

 function groupSum(rows, keyFn, valueFn) {
 const map = {}
;(rows || []).forEach(row => {
 const key = keyFn(row) || 'Unassigned'
 if (!map[key]) map[key] = 0
 map[key] += safeNum(valueFn(row), 0)
 })
 return Object.entries(map).map(([name, total]) => ({ name, total })).sort((a,b)=>b.total-a.total)
 }

 function downloadTextFile(filename, content, mime = 'text/plain') {
 const blob = new Blob([content], { type:mime })
 const url = URL.createObjectURL(blob)
 const a = document.createElement('a')
 a.href = url
 a.download = filename
 document.body.appendChild(a)
 a.click()
 a.remove()
 URL.revokeObjectURL(url)
 }

 function rowsToCSV(rows) {
 if (!rows || rows.length === 0) return ''
 const headers = Array.from(rows.reduce((set, row)=>{ Object.keys(row || {}).forEach(k=>set.add(k)); return set }, new Set()))
 const escape = value => `"${String(value?? '').replace(/"/g, '""')}"`
 return [headers.join(','),...rows.map(row => headers.map(h => escape(row[h])).join(','))].join('\n')
 }

 function getBusinessHealthColor(score) {
 if (score >= 80) return '#2d8a4e'
 if (score >= 60) return '#f5a623'
 return '#ca1b1b'
 }


 function getExecutiveStatusColor(status) {
 const s = String(status || '').toLowerCase()
 if (s.includes('critical') || s.includes('alert') || s.includes('urgent')) return '#ca1b1b'
 if (s.includes('watch') || s.includes('review')) return '#f5a623'
 return '#2d8a4e'
 }

 function buildExecutiveCommandCenter(data) {
 const d = data || {}
 const netSalesBasis = safeNum(d.netSales?? d.totalSales, 0)
 const profitMargin = safeNum(d.netMarginPct, 0)
 const salaryRatio = safeNum(d.salaryToSalesRatio, 0)
 const foodCostRatio = safeNum(d.foodCostPct, 0)
 const returnsRatio = safeNum(d.returnsRate, 0)
 const cashFlowValue = safeNum(d.netCashFlow, 0)
 const totalARValue = safeNum(d.totalAR, 0)
 const overdueARValue = safeNum(d.overdueAR, 0)
 const arOverduePct = totalARValue > 0? (overdueARValue / totalARValue) * 100: 0
 const criticalStock = safeNum(d.inventoryControl?.criticalItems, 0)
 const reorderStock = safeNum(d.inventoryControl?.reorderNowItems, 0)
 const pendingApprovalCount = safeNum(d.totalPendingApprovals?? d.approvalWorkflowSummary?.total, 0)
 const highRiskAudit = safeNum(d.auditReviewSummary?.high, 0)
 const documentCompletion = safeNum(d.employeeDocumentSummary?.completionPct, 100)
 const wastagePctSales = safeNum(d.wastageReport?.pctOfSales, 0)
 const productMargin = safeNum(d.productProfitabilitySummary?.avgMarginPct, 0)

 const riskRows = [
 { area:'Net Profit Margin', value:`${profitMargin.toFixed(1)}%`, target:'Target 15%', status:profitMargin >= 15? 'GOOD': profitMargin >= 10? 'WATCH': 'ALERT', action:profitMargin >= 15? 'Maintain current controls.': 'Review COGS, payroll, returns, and non-payroll expenses.' },
 { area:'Sales-to-Salary Ratio', value:`${salaryRatio.toFixed(1)}%`, target:'Target 25%', status:salaryRatio <= 25? 'GOOD': salaryRatio <= 30? 'WATCH': 'CRITICAL', action:salaryRatio <= 25? 'Payroll is inside target.': 'Control overtime, review staffing, or increase sales volume.' },
 { area:'Food Cost / COGS', value:`${foodCostRatio.toFixed(1)}%`, target:'Target 40%', status:foodCostRatio <= 40? 'GOOD': foodCostRatio <= 50? 'WATCH': 'CRITICAL', action:foodCostRatio <= 40? 'COGS is inside control ceiling.': 'Audit recipe usage, wastage, supplier cost, and batch yield.' },
 { area:'Returns / Unsold', value:`${returnsRatio.toFixed(1)}%`, target:'Target 5%', status:returnsRatio <= 5? 'GOOD': returnsRatio <= 10? 'WATCH': 'CRITICAL', action:returnsRatio <= 5? 'Returns are controlled.': 'Reduce delivery quantity to high-return outlets and adjust forecasting.' },
 { area:'Cash Flow', value:php(cashFlowValue), target:'Positive monthly cash flow', status:cashFlowValue >= 0? 'GOOD': 'ALERT', action:cashFlowValue >= 0? 'Cash flow is positive.': 'Delay non-critical expenses and prioritize collections.' },
 { area:'Receivables', value:php(overdueARValue), target:'Low overdue AR', status:overdueARValue <= 0? 'GOOD': arOverduePct <= 30? 'WATCH': 'CRITICAL', action:overdueARValue <= 0? 'No overdue AR detected.': 'Collect overdue reseller balances before increasing deliveries.' },
 { area:'Inventory Stock Risk', value:`${criticalStock} critical / ${reorderStock} reorder`, target:'0 critical items', status:criticalStock > 0? 'CRITICAL': reorderStock > 0? 'WATCH': 'GOOD', action:criticalStock > 0? 'Reorder critical ingredients/packaging immediately.': reorderStock > 0? 'Prepare purchase orders before stockout.': 'Inventory is stable.' },
 { area:'Approvals', value:`${pendingApprovalCount} pending`, target:'No aging approvals', status:pendingApprovalCount > 8? 'CRITICAL': pendingApprovalCount > 0? 'WATCH': 'GOOD', action:pendingApprovalCount > 0? 'Clear pending leave, CA, OT/UT, disputes, and expenses.': 'Approval queue is clear.' },
 { area:'Audit / Security', value:`${highRiskAudit} high-risk`, target:'0 high-risk actions', status:highRiskAudit > 0? 'ALERT': 'GOOD', action:highRiskAudit > 0? 'Review high-risk audit actions today.': 'No high-risk audit flags detected.' },
 { area:'Employee Documents', value:`${documentCompletion.toFixed(0)}% complete`, target:' 95% complete', status:documentCompletion >= 95? 'GOOD': documentCompletion >= 85? 'WATCH': 'ALERT', action:documentCompletion >= 95? 'HR documents are controlled.': 'Complete missing IDs, contracts, contacts, and government records.' },
 ]

 const alertRows = riskRows.filter(r => ['ALERT','CRITICAL'].includes(r.status))
 const watchRows = riskRows.filter(r => r.status === 'WATCH')
 const goodRows = riskRows.filter(r => r.status === 'GOOD')
 const topRisks = [...alertRows,...watchRows].slice(0, 6)

 const headline = alertRows.length > 0
? `Owner attention needed: ${alertRows.length} critical area(s) require action.`
: watchRows.length > 0
? `Business is stable but ${watchRows.length} area(s) need monitoring.`
: 'Business controls are healthy based on current available data.'

 const nextMove = topRisks[0]?.action || 'Continue daily monitoring and keep records updated.'

 const kpiCards = [
 { label:'Business Health', value:`${safeNum(d.healthScore,0).toFixed(0)}/100`, note:d.businessHealthGrade || 'Overall score', color:getBusinessHealthColor(safeNum(d.healthScore,0)), icon:' ' },
 { label:'Net Sales', value:php(netSalesBasis), note:'After returns / unsold', color:'#1a1a2e', icon:' ' },
 { label:'Net Profit', value:php(d.netProfit), note:`${profitMargin.toFixed(1)}% margin`, color:safeNum(d.netProfit,0) >= 0? '#2d8a4e': '#ca1b1b', icon:' ' },
 { label:'Cash Flow', value:php(cashFlowValue), note:cashFlowValue >= 0? 'Positive cash flow': 'Negative cash flow', color:cashFlowValue >= 0? '#2d8a4e': '#ca1b1b', icon:' ' },
 { label:'Payroll Ratio', value:`${salaryRatio.toFixed(1)}%`, note:'Target 25%', color:salaryRatio <= 25? '#2d8a4e': salaryRatio <= 30? '#f5a623': '#ca1b1b', icon:' ' },
 { label:'Food Cost', value:`${foodCostRatio.toFixed(1)}%`, note:'Target 40%', color:foodCostRatio <= 40? '#2d8a4e': foodCostRatio <= 50? '#f5a623': '#ca1b1b', icon:' ' },
 { label:'Returns', value:`${returnsRatio.toFixed(1)}%`, note:`${safeNum(d.totalReturnsQty,0)} pcs returned`, color:returnsRatio <= 5? '#2d8a4e': returnsRatio <= 10? '#f5a623': '#ca1b1b', icon:' ' },
 { label:'Receivables', value:php(totalARValue), note:`Overdue ${php(overdueARValue)}`, color:overdueARValue <= 0? '#2d8a4e': '#f5a623', icon:' ' },
 { label:'Low Stock', value:`${safeNum(d.lowStockItems?.length,0)} item(s)`, note:`${criticalStock} critical`, color:criticalStock > 0? '#ca1b1b': reorderStock > 0? '#f5a623': '#2d8a4e', icon:' ' },
 { label:'Pending Approvals', value:String(pendingApprovalCount), note:'Owner/admin action queue', color:pendingApprovalCount > 0? '#f5a623': '#2d8a4e', icon:' ' },
 { label:'Wastage', value:`${wastagePctSales.toFixed(1)}%`, note:`Cost ${php(d.wastageReport?.cost || d.wastageCost || 0)}`, color:wastagePctSales <= 5? '#2d8a4e': wastagePctSales <= 8? '#f5a623': '#ca1b1b', icon:' ' },
 { label:'Product Margin', value:`${productMargin.toFixed(1)}%`, note:`${safeNum(d.productProfitabilitySummary?.lowMarginCount,0)} low-margin`, color:productMargin >= 45? '#2d8a4e': productMargin >= 30? '#f5a623': '#ca1b1b', icon:' ' },
 ]

 const dailyChecklist = [
 { task:'Check cash-in vs cash-out and bank deposits', status:cashFlowValue >= 0? 'GOOD': 'DO TODAY', note:cashFlowValue >= 0? 'Cash flow is positive.': 'Negative cash flow needs owner review.' },
 { task:'Collect priority reseller receivables', status:overdueARValue > 0? 'DO TODAY': 'GOOD', note:overdueARValue > 0? `${php(overdueARValue)} overdue AR detected.`: 'No overdue AR detected.' },
 { task:'Review production quantity against forecast', status:(d.productionForecast?.suggestedProductionQty || 0) > 0? 'CHECK': 'SETUP', note:(d.productionForecast?.suggestedProductionQty || 0) > 0? `${safeNum(d.productionForecast?.suggestedProductionQty,0)} pcs suggested.`: 'Need sales/production basis.' },
 { task:'Review returns and reduce high-return deliveries', status:returnsRatio > 5? 'DO TODAY': 'GOOD', note:returnsRatio > 5? `Return rate is ${returnsRatio.toFixed(1)}%.`: 'Returns within target.' },
 { task:'Check critical inventory and reorder alerts', status:criticalStock > 0 || reorderStock > 0? 'DO TODAY': 'GOOD', note:criticalStock > 0? `${criticalStock} critical items.`: reorderStock > 0? `${reorderStock} items need reorder.`: 'Stock status is stable.' },
 { task:'Clear approval queue', status:pendingApprovalCount > 0? 'CHECK': 'GOOD', note:pendingApprovalCount > 0? `${pendingApprovalCount} pending approvals.`: 'No pending approvals.' },
 ]

 const sevenDayPlan = [
 { day:'Day 1', focus:'Cash & AR Collection', action:overdueARValue > 0? 'Collect overdue reseller balances and pause risky credit deliveries.': 'Confirm daily closing and deposit accuracy.' },
 { day:'Day 2', focus:'Production Forecast', action:'Compare forecast quantity vs actual outlet demand and adjust next delivery quantities.' },
 { day:'Day 3', focus:'Food Cost & Wastage', action:'Review top COGS drivers, wastage reasons, and product yield variance.' },
 { day:'Day 4', focus:'Payroll Productivity', action:salaryRatio > 25? 'Review staffing, overtime, and schedule efficiency.': 'Maintain payroll controls and monitor overtime.' },
 { day:'Day 5', focus:'Product Profitability', action:'Push high-margin products and review low-margin or high-return variants.' },
 { day:'Day 6', focus:'Inventory & Purchasing', action:'Create reorder plan for critical ingredients, packaging, and supplies.' },
 { day:'Day 7', focus:'Owner Review', action:'Print/export the Foundation report and review the next week s owner action priorities.' },
 ]

 return {
 headline,
 nextMove,
 status:alertRows.length? 'ALERT': watchRows.length? 'WATCH': 'GOOD',
 statusColor:alertRows.length? '#ca1b1b': watchRows.length? '#f5a623': '#2d8a4e',
 alertCount:alertRows.length,
 watchCount:watchRows.length,
 goodCount:goodRows.length,
 kpiCards,
 riskRows,
 topRisks,
 dailyChecklist,
 sevenDayPlan,
 }
 }

 function getRecentFoundationMonths(monthValue, count = 6) {
 const [year, month] = String(monthValue || today.slice(0,7)).split('-').map(Number)
 const months = []
 for (let i = count - 1; i >= 0; i--) {
 const d = new Date(year, (month || 1) - 1 - i, 1)
 const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
 months.push({
 key,
 label: d.toLocaleString('en-PH', { month:'short', year:'2-digit' }),
...getMonthRange(key)
 })
 }
 return months
 }

 function getSalaryRatioStatus(ratio, sales = 0, payroll = 0) {
 if (safeNum(payroll, 0) <= 0) {
 return { label:'NO PAYROLL DATA', color:'#777', level:'none', message:'Release or post payroll to calculate salary ratio.' }
 }
 if (safeNum(sales, 0) <= 0) {
 return { label:'NO SALES DATA', color:'#ca1b1b', level:'alert', message:'Payroll exists but sales are missing for this period.' }
 }
 if (ratio <= 20) return { label:'GOOD', color:'#2d8a4e', level:'good', message:'Payroll is controlled against sales.' }
 if (ratio <= 25) return { label:'HEALTHY', color:'#2d8a4e', level:'good', message:'Payroll is still inside the target range.' }
 if (ratio <= 30) return { label:'WATCH', color:'#f5a623', level:'watch', message:'Payroll is slightly high. Review scheduling and overtime.' }
 return { label:'CRITICAL', color:'#ca1b1b', level:'critical', message:'Payroll is eating too much of sales. Immediate review is needed.' }
 }

 function getFoodCostStatus(ratio, sales = 0, cogs = 0) {
 if (safeNum(cogs, 0) <= 0) {
 return { label:'NO COGS DATA', color:'#777', level:'none', message:'Encode production costs or production logs to calculate food cost accurately.' }
 }
 if (safeNum(sales, 0) <= 0) {
 return { label:'NO SALES DATA', color:'#ca1b1b', level:'alert', message:'COGS exists but sales are missing for this period.' }
 }
 if (ratio < 25) return { label:'LOW / CHECK DATA', color:'#4a90d9', level:'check', message:'Food cost is unusually low. Confirm that all production costs were encoded.' }
 if (ratio <= 35) return { label:'GOOD', color:'#2d8a4e', level:'good', message:'Food cost is controlled and leaves room for payroll and profit.' }
 if (ratio <= 40) return { label:'HEALTHY', color:'#2d8a4e', level:'good', message:'Food cost is inside the upper healthy range.' }
 if (ratio <= 50) return { label:'WATCH', color:'#f5a623', level:'watch', message:'Food cost is high. Check ingredient prices, wastage, yield, and selling prices.' }
 return { label:'CRITICAL', color:'#ca1b1b', level:'critical', message:'Food cost is too high and may destroy profitability. Immediate action is needed.' }
 }

 function getReturnsStatus(ratio, qty = 0, amount = 0, grossSalesValue = 0) {
 if (safeNum(qty, 0) <= 0 && safeNum(amount, 0) <= 0) {
 return { label:'NO RETURNS', color:'#2d8a4e', level:'good', message:'No returns or unsold donut loss recorded for this period.' }
 }
 if (safeNum(grossSalesValue, 0) <= 0) {
 return { label:'CHECK SALES DATA', color:'#f5a623', level:'watch', message:'Returns exist, but gross sales are missing. Confirm sales and invoice encoding.' }
 }
 if (ratio <= 3) return { label:'EXCELLENT', color:'#2d8a4e', level:'good', message:'Returns are very controlled. Maintain current forecasting and ordering discipline.' }
 if (ratio <= 5) return { label:'GOOD', color:'#2d8a4e', level:'good', message:'Returns are within the healthy control target.' }
 if (ratio <= 10) return { label:'WATCH', color:'#f5a623', level:'watch', message:'Returns are above ideal. Review forecasting, delivery quantities, and slow-moving outlets.' }
 return { label:'CRITICAL', color:'#ca1b1b', level:'critical', message:'Returns are too high. Immediate action is needed to protect cash flow and profit.' }
 }



 function getReceivableStatus(totalARValue, overdueValue, salesValue) {
 const ar = safeNum(totalARValue, 0)
 const overdue = safeNum(overdueValue, 0)
 const sales = safeNum(salesValue, 0)
 if (ar <= 0) return { label:'CLEAR', color:'#2d8a4e', level:'good', message:'No unpaid reseller receivables detected for this period.' }
 const arPct = sales > 0? (ar / sales) * 100: 0
 const overduePct = ar > 0? (overdue / ar) * 100: 0
 if (arPct <= 10 && overduePct <= 20) return { label:'GOOD', color:'#2d8a4e', level:'good', message:'Receivables are controlled. Continue regular collection discipline.' }
 if (arPct <= 20 && overduePct <= 40) return { label:'WATCH', color:'#f5a623', level:'watch', message:'Receivables are rising. Follow up accounts before they become collection problems.' }
 return { label:'CRITICAL', color:'#ca1b1b', level:'critical', message:'Receivables are high. Prioritize collections before releasing more credit.' }
 }

 function getCashFlowStatus(netCash, cashInValue, cashOutValue) {
 const net = safeNum(netCash, 0)
 const inflow = safeNum(cashInValue, 0)
 const outflow = safeNum(cashOutValue, 0)
 if (inflow <= 0 && outflow <= 0) return { label:'NO CASH DATA', color:'#777', level:'none', message:'Encode sales, collections, expenses, and deposits to read cash flow.' }
 if (net > 0 && inflow >= outflow * 1.1) return { label:'HEALTHY', color:'#2d8a4e', level:'good', message:'Cash inflow is stronger than outflow for this period.' }
 if (net >= 0) return { label:'STABLE', color:'#2d8a4e', level:'good', message:'Cash flow is positive, but keep monitoring expenses and receivables.' }
 if (Math.abs(net) <= outflow * 0.15) return { label:'WATCH', color:'#f5a623', level:'watch', message:'Cash flow is slightly negative. Review collections and spending.' }
 return { label:'CRITICAL', color:'#ca1b1b', level:'critical', message:'Cash outflow is materially higher than inflow. Immediate cash control is needed.' }
 }

 function getPerformanceStatus(score) {
 const s = safeNum(score, 0)
 if (s >= 85) return { label:'EXCELLENT', color:'#2d8a4e' }
 if (s >= 70) return { label:'GOOD', color:'#2d8a4e' }
 if (s >= 50) return { label:'WATCH', color:'#f5a623' }
 return { label:'CRITICAL', color:'#ca1b1b' }
 }


 function getInventoryRiskStatus(current, minimum) {
 const cur = safeNum(current, 0)
 const min = safeNum(minimum, 0)
 if (min <= 0) return { label:'NO MINIMUM SET', color:'#777', level:'none', message:'Set minimum stock to activate reorder control.' }
 if (cur <= 0) return { label:'STOCKOUT', color:'#ca1b1b', level:'critical', message:'Item is out of stock. Reorder immediately.' }
 if (cur <= min * 0.50) return { label:'CRITICAL', color:'#ca1b1b', level:'critical', message:'Stock is critically below minimum. Reorder immediately.' }
 if (cur <= min) return { label:'REORDER NOW', color:'#f5a623', level:'watch', message:'Stock reached reorder point.' }
 if (cur <= min * 1.50) return { label:'WATCH', color:'#f5a623', level:'watch', message:'Stock is close to reorder point.' }
 return { label:'HEALTHY', color:'#2d8a4e', level:'good', message:'Stock is above reorder level.' }
 }

 function getYieldStatus(yieldPctValue, expectedValue = 0, actualValue = 0) {
 const expected = safeNum(expectedValue, 0)
 const actual = safeNum(actualValue, 0)
 const pct = safeNum(yieldPctValue, 0)
 if (expected <= 0 && actual <= 0) return { label:'NO PRODUCTION DATA', color:'#777', level:'none', message:'Encode production reports or production logs to monitor yield.' }
 if (expected <= 0) return { label:'NO STANDARD YET', color:'#4a90d9', level:'check', message:'Actual output exists, but expected/standard output is not yet encoded.' }
 if (pct >= 98) return { label:'EXCELLENT', color:'#2d8a4e', level:'good', message:'Production yield is very close to expected output.' }
 if (pct >= 95) return { label:'GOOD', color:'#2d8a4e', level:'good', message:'Production yield is within the healthy control range.' }
 if (pct >= 90) return { label:'WATCH', color:'#f5a623', level:'watch', message:'Yield is below target. Review rejects, proofing, scaling, frying, and handling losses.' }
 return { label:'CRITICAL', color:'#ca1b1b', level:'critical', message:'Yield loss is high. Immediate production audit is needed.' }
 }

 function getRouteStatus(invoiceStatus, returnRate = 0, balance = 0) {
 const status = String(invoiceStatus || '').toLowerCase()
 if (balance > 0 && (status.includes('unpaid') || status.includes('partial'))) return { label:'DELIVERED / UNCOLLECTED', color:'#f5a623', level:'watch' }
 if (safeNum(returnRate, 0) > 10) return { label:'HIGH RETURNS', color:'#ca1b1b', level:'critical' }
 if (safeNum(returnRate, 0) > 5) return { label:'RETURN WATCH', color:'#f5a623', level:'watch' }
 if (status.includes('paid') || status.includes('delivered') || status.includes('partial')) return { label:'COMPLETED', color:'#2d8a4e', level:'good' }
 return { label:'PENDING / CHECK', color:'#777', level:'none' }
 }


 function getWastageCostStatus(wastagePct, cost = 0, cogs = 0) {
 const amount = safeNum(cost, 0)
 const base = safeNum(cogs, 0)
 const pct = safeNum(wastagePct, 0)
 if (amount <= 0) return { label:'CONTROLLED', color:'#2d8a4e', level:'good', message:'No wastage cost recorded for this period.' }
 if (base <= 0) return { label:'CHECK COGS DATA', color:'#f5a623', level:'watch', message:'Wastage exists but COGS/production cost is missing. Encode production cost to read the real impact.' }
 if (pct <= 2) return { label:'EXCELLENT', color:'#2d8a4e', level:'good', message:'Wastage cost is very low against production cost.' }
 if (pct <= 5) return { label:'HEALTHY', color:'#2d8a4e', level:'good', message:'Wastage is inside the normal control range.' }
 if (pct <= 8) return { label:'WATCH', color:'#f5a623', level:'watch', message:'Wastage is above ideal. Review product handling, overproduction, and rejected items.' }
 return { label:'CRITICAL', color:'#ca1b1b', level:'critical', message:'Wastage cost is too high. Immediate production and accountability review is needed.' }
 }

 function getProductProfitStatus(marginPct, revenue = 0, cogs = 0) {
 const sales = safeNum(revenue, 0)
 const cost = safeNum(cogs, 0)
 const margin = safeNum(marginPct, 0)
 if (sales <= 0) return { label:'NO SALES', color:'#777', level:'none', message:'No sales detected for this product.' }
 if (cost <= 0) return { label:'NEEDS COGS', color:'#4a90d9', level:'check', message:'Sales exist but COGS is estimated or missing. Add costing data for accuracy.' }
 if (margin >= 45) return { label:'HIGH PROFIT', color:'#2d8a4e', level:'good', message:'Strong product margin.' }
 if (margin >= 30) return { label:'GOOD', color:'#2d8a4e', level:'good', message:'Healthy product margin.' }
 if (margin >= 15) return { label:'WATCH', color:'#f5a623', level:'watch', message:'Margin is thin. Review price, toppings, filling, and labor handling.' }
 return { label:'LOW / CRITICAL', color:'#ca1b1b', level:'critical', message:'Low product margin. Review cost, pricing, returns, and portion control.' }
 }
